    // Multi-master (3 masters) → mem0
    //   - cpu (rw)
    //   - io (rw)
    //   - acc (rw)

    wire cpu_64b_aw_to_mem0 = (cpu_64b_aw.addr <= 32'h0fffffff);
    wire cpu_64b_ar_to_mem0 = (cpu_64b_ar.addr <= 32'h0fffffff);
    wire io_64b_aw_to_mem0 = (io_64b_aw.addr <= 32'h0fffffff);
    wire io_64b_ar_to_mem0 = (io_64b_ar.addr <= 32'h0fffffff);
    wire acc_64b_aw_to_mem0 = (acc_64b_aw.addr <= 32'h0fffffff);
    wire acc_64b_ar_to_mem0 = (acc_64b_ar.addr <= 32'h0fffffff);

    // AW request slots for mem0: arbitration at the slave pins
    assign cpu_64b_aw_slot_mem0_in_valid = cpu_64b_aw_to_mem0 && cpu_64b_awvalid && !(cpu_64b_aw_hold_mem0 || (|cpu_32b_wlive_mem2) || cpu_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_cpu_64b_aw_slot_mem0 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_64b_aw_slot_mem0_in_valid), .wr_ready(cpu_64b_aw_slot_mem0_in_ready), .wr_data(cpu_64b_aw),
        .rd_valid(cpu_64b_aw_slot_mem0_valid), .rd_ready(cpu_64b_aw_slot_mem0_ready), .rd_data(cpu_64b_aw_slot_mem0),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign io_64b_aw_slot_mem0_in_valid = io_64b_aw_to_mem0 && io_64b_awvalid && !(io_64b_aw_hold_mem0 || (|io_32b_wlive_mem2) || io_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_io_64b_aw_slot_mem0 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(io_64b_aw_slot_mem0_in_valid), .wr_ready(io_64b_aw_slot_mem0_in_ready), .wr_data(io_64b_aw),
        .rd_valid(io_64b_aw_slot_mem0_valid), .rd_ready(io_64b_aw_slot_mem0_ready), .rd_data(io_64b_aw_slot_mem0),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign acc_64b_aw_slot_mem0_in_valid = acc_64b_aw_to_mem0 && acc_64b_awvalid && !(acc_64b_aw_hold_mem0 || (|acc_32b_wlive_mem2) || acc_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_acc_64b_aw_slot_mem0 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(acc_64b_aw_slot_mem0_in_valid), .wr_ready(acc_64b_aw_slot_mem0_in_ready), .wr_data(acc_64b_aw),
        .rd_valid(acc_64b_aw_slot_mem0_valid), .rd_ready(acc_64b_aw_slot_mem0_ready), .rd_data(acc_64b_aw_slot_mem0),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AW arbiter for mem0: round-robin, lock until handshake ----
    logic [2:0] mem0_aw_arb_req;
    assign mem0_aw_arb_req = {acc_64b_aw_slot_mem0_valid, io_64b_aw_slot_mem0_valid, cpu_64b_aw_slot_mem0_valid};
    logic [1:0] mem0_aw_arb_lock, mem0_aw_arb_rr;
    logic mem0_aw_arb_locked;
    wire [1:0] mem0_aw_arb_pick = (mem0_aw_arb_rr == 2'd0) ? (mem0_aw_arb_req[0] ? 2'd0 : mem0_aw_arb_req[1] ? 2'd1 : 2'd2) : 
        (mem0_aw_arb_rr == 2'd1) ? (mem0_aw_arb_req[1] ? 2'd1 : mem0_aw_arb_req[2] ? 2'd2 : 2'd0) : 
        mem0_aw_arb_req[2] ? 2'd2 : mem0_aw_arb_req[0] ? 2'd0 : 2'd1;
    wire mem0_aw_arb_gnt_valid = mem0_aw_arb_locked || (|mem0_aw_arb_req);
    wire [1:0] mem0_aw_arb_gnt = mem0_aw_arb_locked ? mem0_aw_arb_lock : mem0_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            mem0_aw_arb_lock   <= '0;
            mem0_aw_arb_rr     <= '0;
            mem0_aw_arb_locked <= 1'b0;
        end else begin
            if (mem0_axi_awvalid && mem0_axi_awready) begin
                mem0_aw_arb_locked <= 1'b0;
                mem0_aw_arb_rr <= (mem0_aw_arb_gnt == 2'd2) ? 2'd0 : mem0_aw_arb_gnt + 1'b1;
            end else if (mem0_axi_awvalid) begin
                mem0_aw_arb_lock   <= mem0_aw_arb_gnt;
                mem0_aw_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_64b_aw_gnt_mem0 = mem0_aw_arb_gnt_valid && (mem0_aw_arb_gnt == 2'd0) && mem0_aw_arb_req[0];
    wire io_64b_aw_gnt_mem0 = mem0_aw_arb_gnt_valid && (mem0_aw_arb_gnt == 2'd1) && mem0_aw_arb_req[1];
    wire acc_64b_aw_gnt_mem0 = mem0_aw_arb_gnt_valid && (mem0_aw_arb_gnt == 2'd2) && mem0_aw_arb_req[2];
    assign cpu_64b_aw_slot_mem0_ready = cpu_64b_aw_gnt_mem0 && mem0_axi_awready;
    assign io_64b_aw_slot_mem0_ready = io_64b_aw_gnt_mem0 && mem0_axi_awready;
    assign acc_64b_aw_slot_mem0_ready = acc_64b_aw_gnt_mem0 && mem0_axi_awready;

    // AW channel (arbitrated mux across writing masters)
    assign mem0_axi_awid = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.id : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.id : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.id : '0);
    assign mem0_axi_awaddr = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.addr : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.addr : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.addr : '0);
    assign mem0_axi_awlen = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.len : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.len : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.len : '0);
    assign mem0_axi_awsize = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.size : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.size : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.size : '0);
    assign mem0_axi_awburst = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.burst : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.burst : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.burst : '0);
    assign mem0_axi_awlock = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.lock : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.lock : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.lock : '0);
    assign mem0_axi_awcache = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.cache : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.cache : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.cache : '0);
    assign mem0_axi_awprot = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.prot : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.prot : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.prot : '0);
    assign mem0_axi_awqos = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.qos : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.qos : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.qos : '0);
    assign mem0_axi_awregion = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.region : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.region : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.region : '0);
    assign mem0_axi_awuser = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.user : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.user : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.user : '0);
    assign mem0_axi_awnsaid = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.nsaid : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.nsaid : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.nsaid : '0);
    assign mem0_axi_awtrace = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.trace : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.trace : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.trace : '0);
    assign mem0_axi_awmpam = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.mpam : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.mpam : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.mpam : '0);
    assign mem0_axi_awmecid = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.mecid : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.mecid : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.mecid : '0);
    assign mem0_axi_awidunq = (cpu_64b_aw_gnt_mem0 ? cpu_64b_aw_slot_mem0.idunq : '0) |
        (io_64b_aw_gnt_mem0 ? io_64b_aw_slot_mem0.idunq : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_64b_aw_slot_mem0.idunq : '0);
    assign mem0_axi_awvalid = cpu_64b_aw_gnt_mem0 || io_64b_aw_gnt_mem0 || acc_64b_aw_gnt_mem0;

    // W owner FIFO: slave-side AW pick order owns the W channel
    // (16 deep: max_outstanding 16)
    logic [1:0] mem0_wowner_mem [16];
    logic [4:0] mem0_wowner_wptr, mem0_wowner_rptr;
    logic mem0_wowner_ahead;
    wire mem0_wowner_valid = (mem0_wowner_wptr != mem0_wowner_rptr);
    wire mem0_wowner_byp = !mem0_wowner_valid && !mem0_wowner_ahead && mem0_axi_awvalid;
    wire mem0_wowner_aw_hs = mem0_axi_awvalid && mem0_axi_awready;
    wire mem0_wowner_w_end = mem0_axi_wvalid && mem0_axi_wready && mem0_axi_wlast;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            mem0_wowner_wptr  <= '0;
            mem0_wowner_rptr  <= '0;
            mem0_wowner_ahead <= 1'b0;
        end else begin
            if (mem0_wowner_aw_hs && mem0_wowner_ahead) begin
                mem0_wowner_ahead <= 1'b0;   // its W already went
            end else if (mem0_wowner_aw_hs && !(mem0_wowner_byp && mem0_wowner_w_end)) begin
                mem0_wowner_mem[mem0_wowner_wptr[3:0]] <= mem0_aw_arb_gnt;
                mem0_wowner_wptr <= mem0_wowner_wptr + 1'b1;
            end else if (!mem0_wowner_aw_hs && mem0_wowner_byp && mem0_wowner_w_end) begin
                mem0_wowner_ahead <= 1'b1;
            end
            if (mem0_wowner_valid && mem0_wowner_w_end) begin
                mem0_wowner_rptr <= mem0_wowner_rptr + 1'b1;
            end
        end
    )
    wire [1:0] mem0_wowner_head = mem0_wowner_valid ? mem0_wowner_mem[mem0_wowner_rptr[3:0]]
                                       : mem0_aw_arb_gnt;
    assign cpu_64b_w_sel_mem0 = (mem0_wowner_valid || mem0_wowner_byp) && (mem0_wowner_head == 2'd0) && cpu_64b_w_to_mem0;
    assign io_64b_w_sel_mem0 = (mem0_wowner_valid || mem0_wowner_byp) && (mem0_wowner_head == 2'd1) && io_64b_w_to_mem0;
    assign acc_64b_w_sel_mem0 = (mem0_wowner_valid || mem0_wowner_byp) && (mem0_wowner_head == 2'd2) && acc_64b_w_to_mem0;

    // W channel (owner-gated mux across writing masters)
    assign mem0_axi_wdata = ((cpu_64b_w_sel_mem0 && cpu_64b_wvalid) ? cpu_64b_w.data : '0) |
        ((io_64b_w_sel_mem0 && io_64b_wvalid) ? io_64b_w.data : '0) |
        ((acc_64b_w_sel_mem0 && acc_64b_wvalid) ? acc_64b_w.data : '0);
    assign mem0_axi_wstrb = ((cpu_64b_w_sel_mem0 && cpu_64b_wvalid) ? cpu_64b_w.strb : '0) |
        ((io_64b_w_sel_mem0 && io_64b_wvalid) ? io_64b_w.strb : '0) |
        ((acc_64b_w_sel_mem0 && acc_64b_wvalid) ? acc_64b_w.strb : '0);
    assign mem0_axi_wlast = ((cpu_64b_w_sel_mem0 && cpu_64b_wvalid) ? cpu_64b_w.last : '0) |
        ((io_64b_w_sel_mem0 && io_64b_wvalid) ? io_64b_w.last : '0) |
        ((acc_64b_w_sel_mem0 && acc_64b_wvalid) ? acc_64b_w.last : '0);
    assign mem0_axi_wuser = ((cpu_64b_w_sel_mem0 && cpu_64b_wvalid) ? cpu_64b_w.user : '0) |
        ((io_64b_w_sel_mem0 && io_64b_wvalid) ? io_64b_w.user : '0) |
        ((acc_64b_w_sel_mem0 && acc_64b_wvalid) ? acc_64b_w.user : '0);
    assign mem0_axi_wvalid = (cpu_64b_w_sel_mem0 && cpu_64b_wvalid) || (io_64b_w_sel_mem0 && io_64b_wvalid) || (acc_64b_w_sel_mem0 && acc_64b_wvalid);

    // Bready (slave -> the master whose response arbiter granted it)
    assign mem0_axi_bready = (cpu_64b_b_rgnt_mem0 ? cpu_64b_bready : '0) |
        (io_64b_b_rgnt_mem0 ? io_64b_bready : '0) |
        (acc_64b_b_rgnt_mem0 ? acc_64b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign mem0_axi_bridge_id_aw = (cpu_64b_aw_gnt_mem0 ? cpu_bridge_id_aw : '0) |
        (io_64b_aw_gnt_mem0 ? io_bridge_id_aw : '0) |
        (acc_64b_aw_gnt_mem0 ? acc_bridge_id_aw : '0);

    // AR request slots for mem0: arbitration at the slave pins
    assign cpu_64b_ar_slot_mem0_in_valid = cpu_64b_ar_to_mem0 && cpu_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_cpu_64b_ar_slot_mem0 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_64b_ar_slot_mem0_in_valid), .wr_ready(cpu_64b_ar_slot_mem0_in_ready), .wr_data(cpu_64b_ar),
        .rd_valid(cpu_64b_ar_slot_mem0_valid), .rd_ready(cpu_64b_ar_slot_mem0_ready), .rd_data(cpu_64b_ar_slot_mem0),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign io_64b_ar_slot_mem0_in_valid = io_64b_ar_to_mem0 && io_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_io_64b_ar_slot_mem0 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(io_64b_ar_slot_mem0_in_valid), .wr_ready(io_64b_ar_slot_mem0_in_ready), .wr_data(io_64b_ar),
        .rd_valid(io_64b_ar_slot_mem0_valid), .rd_ready(io_64b_ar_slot_mem0_ready), .rd_data(io_64b_ar_slot_mem0),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign acc_64b_ar_slot_mem0_in_valid = acc_64b_ar_to_mem0 && acc_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_acc_64b_ar_slot_mem0 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(acc_64b_ar_slot_mem0_in_valid), .wr_ready(acc_64b_ar_slot_mem0_in_ready), .wr_data(acc_64b_ar),
        .rd_valid(acc_64b_ar_slot_mem0_valid), .rd_ready(acc_64b_ar_slot_mem0_ready), .rd_data(acc_64b_ar_slot_mem0),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AR arbiter for mem0: round-robin, lock until handshake ----
    logic [2:0] mem0_ar_arb_req;
    assign mem0_ar_arb_req = {acc_64b_ar_slot_mem0_valid, io_64b_ar_slot_mem0_valid, cpu_64b_ar_slot_mem0_valid};
    logic [1:0] mem0_ar_arb_lock, mem0_ar_arb_rr;
    logic mem0_ar_arb_locked;
    wire [1:0] mem0_ar_arb_pick = (mem0_ar_arb_rr == 2'd0) ? (mem0_ar_arb_req[0] ? 2'd0 : mem0_ar_arb_req[1] ? 2'd1 : 2'd2) : 
        (mem0_ar_arb_rr == 2'd1) ? (mem0_ar_arb_req[1] ? 2'd1 : mem0_ar_arb_req[2] ? 2'd2 : 2'd0) : 
        mem0_ar_arb_req[2] ? 2'd2 : mem0_ar_arb_req[0] ? 2'd0 : 2'd1;
    wire mem0_ar_arb_gnt_valid = mem0_ar_arb_locked || (|mem0_ar_arb_req);
    wire [1:0] mem0_ar_arb_gnt = mem0_ar_arb_locked ? mem0_ar_arb_lock : mem0_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            mem0_ar_arb_lock   <= '0;
            mem0_ar_arb_rr     <= '0;
            mem0_ar_arb_locked <= 1'b0;
        end else begin
            if (mem0_axi_arvalid && mem0_axi_arready) begin
                mem0_ar_arb_locked <= 1'b0;
                mem0_ar_arb_rr <= (mem0_ar_arb_gnt == 2'd2) ? 2'd0 : mem0_ar_arb_gnt + 1'b1;
            end else if (mem0_axi_arvalid) begin
                mem0_ar_arb_lock   <= mem0_ar_arb_gnt;
                mem0_ar_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_64b_ar_gnt_mem0 = mem0_ar_arb_gnt_valid && (mem0_ar_arb_gnt == 2'd0) && mem0_ar_arb_req[0];
    wire io_64b_ar_gnt_mem0 = mem0_ar_arb_gnt_valid && (mem0_ar_arb_gnt == 2'd1) && mem0_ar_arb_req[1];
    wire acc_64b_ar_gnt_mem0 = mem0_ar_arb_gnt_valid && (mem0_ar_arb_gnt == 2'd2) && mem0_ar_arb_req[2];
    assign cpu_64b_ar_slot_mem0_ready = cpu_64b_ar_gnt_mem0 && mem0_axi_arready;
    assign io_64b_ar_slot_mem0_ready = io_64b_ar_gnt_mem0 && mem0_axi_arready;
    assign acc_64b_ar_slot_mem0_ready = acc_64b_ar_gnt_mem0 && mem0_axi_arready;

    // AR channel (arbitrated mux across reading masters)
    assign mem0_axi_arid = (cpu_64b_ar_gnt_mem0 ? cpu_64b_ar_slot_mem0.id : '0) |
        (io_64b_ar_gnt_mem0 ? io_64b_ar_slot_mem0.id : '0) |
        (acc_64b_ar_gnt_mem0 ? acc_64b_ar_slot_mem0.id : '0);
    assign mem0_axi_araddr = (cpu_64b_ar_gnt_mem0 ? cpu_64b_ar_slot_mem0.addr : '0) |
        (io_64b_ar_gnt_mem0 ? io_64b_ar_slot_mem0.addr : '0) |
        (acc_64b_ar_gnt_mem0 ? acc_64b_ar_slot_mem0.addr : '0);
    assign mem0_axi_arlen = (cpu_64b_ar_gnt_mem0 ? cpu_64b_ar_slot_mem0.len : '0) |
        (io_64b_ar_gnt_mem0 ? io_64b_ar_slot_mem0.len : '0) |
        (acc_64b_ar_gnt_mem0 ? acc_64b_ar_slot_mem0.len : '0);
    assign mem0_axi_arsize = (cpu_64b_ar_gnt_mem0 ? cpu_64b_ar_slot_mem0.size : '0) |
        (io_64b_ar_gnt_mem0 ? io_64b_ar_slot_mem0.size : '0) |
        (acc_64b_ar_gnt_mem0 ? acc_64b_ar_slot_mem0.size : '0);
    assign mem0_axi_arburst = (cpu_64b_ar_gnt_mem0 ? cpu_64b_ar_slot_mem0.burst : '0) |
        (io_64b_ar_gnt_mem0 ? io_64b_ar_slot_mem0.burst : '0) |
        (acc_64b_ar_gnt_mem0 ? acc_64b_ar_slot_mem0.burst : '0);
    assign mem0_axi_arlock = (cpu_64b_ar_gnt_mem0 ? cpu_64b_ar_slot_mem0.lock : '0) |
        (io_64b_ar_gnt_mem0 ? io_64b_ar_slot_mem0.lock : '0) |
        (acc_64b_ar_gnt_mem0 ? acc_64b_ar_slot_mem0.lock : '0);
