        (io_64b_ar_gnt_mem0 ? io_64b_ar_slot_mem0.prot : '0) |
        (acc_64b_ar_gnt_mem0 ? acc_64b_ar_slot_mem0.prot : '0);
    assign mem0_axi_arqos = (cpu_64b_ar_gnt_mem0 ? cpu_64b_ar_slot_mem0.qos : '0) |
        (io_64b_ar_gnt_mem0 ? io_64b_ar_slot_mem0.qos : '0) |
