    assign mem0_axi_artrace = (cpu_64b_ar_gnt_mem0 ? cpu_64b_ar_slot_mem0.trace : '0) |
        (io_64b_ar_gnt_mem0 ? io_64b_ar_slot_mem0.trace : '0) |
        (acc_64b_ar_gnt_mem0 ? acc_64b_ar_slot_mem0.trace : '0);
    assign mem0_axi_armpam = (cpu_64b_ar_gnt_mem0 ? cpu_64b_ar_slot_mem0.mpam : '0) |
