        (acc_64b_ar_gnt_mem0 ? acc_64b_ar_slot_mem0.mecid : '0);
    assign mem0_axi_aridunq = (cpu_64b_ar_gnt_mem0 ? cpu_64b_ar_slot_mem0.idunq : '0) |
        (io_64b_ar_gnt_mem0 ? io_64b_ar_slot_mem0.idunq : '0) |
        (acc_64b_ar_gnt_mem0 ? acc_64b_ar_slot_mem0.idunq : '0);
    assign mem0_axi_arvalid = cpu_64b_ar_gnt_mem0 || io_64b_ar_gnt_mem0 || acc_64b_ar_gnt_mem0;

    // Rready (slave -> the master whose response arbiter granted it)
    assign mem0_axi_rready = (cpu_64b_r_rgnt_mem0 ? cpu_64b_rready : '0) |
