        (io_64b_ar_gnt_mem0 ? io_bridge_id_ar : '0) |
        (acc_64b_ar_gnt_mem0 ? acc_bridge_id_ar : '0);


    // ================================================================
    // Slave 1: mem1 (64b)
    // ================================================================
    // Multi-master (3 masters) → mem1
    //   - cpu (rw)
    //   - io (rw)
    //   - acc (rw)

    wire cpu_64b_aw_to_mem1 = ((cpu_64b_aw.addr >= 32'h10000000) && (cpu_64b_aw.addr <= 32'h1fffffff));
    wire cpu_64b_ar_to_mem1 = ((cpu_64b_ar.addr >= 32'h10000000) && (cpu_64b_ar.addr <= 32'h1fffffff));
    wire io_64b_aw_to_mem1 = ((io_64b_aw.addr >= 32'h10000000) && (io_64b_aw.addr <= 32'h1fffffff));
    wire io_64b_ar_to_mem1 = ((io_64b_ar.addr >= 32'h10000000) && (io_64b_ar.addr <= 32'h1fffffff));
    wire acc_64b_aw_to_mem1 = ((acc_64b_aw.addr >= 32'h10000000) && (acc_64b_aw.addr <= 32'h1fffffff));
    wire acc_64b_ar_to_mem1 = ((acc_64b_ar.addr >= 32'h10000000) && (acc_64b_ar.addr <= 32'h1fffffff));

    // AW request slots for mem1: arbitration at the slave pins
    assign cpu_64b_aw_slot_mem1_in_valid = cpu_64b_aw_to_mem1 && cpu_64b_awvalid && !(cpu_64b_aw_hold_mem1 || (|cpu_32b_wlive_mem2) || cpu_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_cpu_64b_aw_slot_mem1 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
