        .wr_valid(acc_64b_aw_slot_mem1_in_valid), .wr_ready(acc_64b_aw_slot_mem1_in_ready), .wr_data(acc_64b_aw),
        .rd_valid(acc_64b_aw_slot_mem1_valid), .rd_ready(acc_64b_aw_slot_mem1_ready), .rd_data(acc_64b_aw_slot_mem1),
