    // ---- AW arbiter for mem1: round-robin, lock until handshake ----
    logic [2:0] mem1_aw_arb_req;
    assign mem1_aw_arb_req = {acc_64b_aw_slot_mem1_valid, io_64b_aw_slot_mem1_valid, cpu_64b_aw_slot_mem1_valid};
