    wire acc_64b_aw_gnt_mem1 = mem1_aw_arb_gnt_valid && (mem1_aw_arb_gnt == 2'd2) && mem1_aw_arb_req[2];
    assign cpu_64b_aw_slot_mem1_ready = cpu_64b_aw_gnt_mem1 && mem1_axi_awready;
    assign io_64b_aw_slot_mem1_ready = io_64b_aw_gnt_mem1 && mem1_axi_awready;
    assign acc_64b_aw_slot_mem1_ready = acc_64b_aw_gnt_mem1 && mem1_axi_awready;

