        (acc_64b_aw_gnt_mem1 ? acc_64b_aw_slot_mem1.addr : '0);
    assign mem1_axi_awlen = (cpu_64b_aw_gnt_mem1 ? cpu_64b_aw_slot_mem1.len : '0) |
