        (acc_64b_aw_gnt_mem1 ? acc_64b_aw_slot_mem1.burst : '0);
    assign mem1_axi_awlock = (cpu_64b_aw_gnt_mem1 ? cpu_64b_aw_slot_mem1.lock : '0) |
        (io_64b_aw_gnt_mem1 ? io_64b_aw_slot_mem1.lock : '0) |
        (acc_64b_aw_gnt_mem1 ? acc_64b_aw_slot_mem1.lock : '0);
    assign mem1_axi_awcache = (cpu_64b_aw_gnt_mem1 ? cpu_64b_aw_slot_mem1.cache : '0) |
        (io_64b_aw_gnt_mem1 ? io_64b_aw_slot_mem1.cache : '0) |
        (acc_64b_aw_gnt_mem1 ? acc_64b_aw_slot_mem1.cache : '0);
    assign mem1_axi_awprot = (cpu_64b_aw_gnt_mem1 ? cpu_64b_aw_slot_mem1.prot : '0) |
        (io_64b_aw_gnt_mem1 ? io_64b_aw_slot_mem1.prot : '0) |
        (acc_64b_aw_gnt_mem1 ? acc_64b_aw_slot_mem1.prot : '0);
    assign mem1_axi_awqos = (cpu_64b_aw_gnt_mem1 ? cpu_64b_aw_slot_mem1.qos : '0) |
        (io_64b_aw_gnt_mem1 ? io_64b_aw_slot_mem1.qos : '0) |
        (acc_64b_aw_gnt_mem1 ? acc_64b_aw_slot_mem1.qos : '0);
