        (io_64b_aw_gnt_mem1 ? io_64b_aw_slot_mem1.user : '0) |
        (acc_64b_aw_gnt_mem1 ? acc_64b_aw_slot_mem1.user : '0);
    assign mem1_axi_awvalid = cpu_64b_aw_gnt_mem1 || io_64b_aw_gnt_mem1 || acc_64b_aw_gnt_mem1;

