    wire mem1_wowner_byp = !mem1_wowner_valid && !mem1_wowner_ahead && mem1_axi_awvalid;
    wire mem1_wowner_aw_hs = mem1_axi_awvalid && mem1_axi_awready;
    wire mem1_wowner_w_end = mem1_axi_wvalid && mem1_axi_wready && mem1_axi_wlast;
