    assign cpu_64b_w_sel_mem1 = (mem1_wowner_valid || mem1_wowner_byp) && (mem1_wowner_head == 2'd0) && cpu_64b_w_to_mem1;
    assign io_64b_w_sel_mem1 = (mem1_wowner_valid || mem1_wowner_byp) && (mem1_wowner_head == 2'd1) && io_64b_w_to_mem1;
    assign acc_64b_w_sel_mem1 = (mem1_wowner_valid || mem1_wowner_byp) && (mem1_wowner_head == 2'd2) && acc_64b_w_to_mem1;

