    assign mem1_axi_wdata = ((cpu_64b_w_sel_mem1 && cpu_64b_wvalid) ? cpu_64b_w.data : '0) |
        ((io_64b_w_sel_mem1 && io_64b_wvalid) ? io_64b_w.data : '0) |
        ((acc_64b_w_sel_mem1 && acc_64b_wvalid) ? acc_64b_w.data : '0);
    assign mem1_axi_wstrb = ((cpu_64b_w_sel_mem1 && cpu_64b_wvalid) ? cpu_64b_w.strb : '0) |
        ((io_64b_w_sel_mem1 && io_64b_wvalid) ? io_64b_w.strb : '0) |
        ((acc_64b_w_sel_mem1 && acc_64b_wvalid) ? acc_64b_w.strb : '0);
    assign mem1_axi_wlast = ((cpu_64b_w_sel_mem1 && cpu_64b_wvalid) ? cpu_64b_w.last : '0) |
        ((io_64b_w_sel_mem1 && io_64b_wvalid) ? io_64b_w.last : '0) |
        ((acc_64b_w_sel_mem1 && acc_64b_wvalid) ? acc_64b_w.last : '0);
    assign mem1_axi_wuser = ((cpu_64b_w_sel_mem1 && cpu_64b_wvalid) ? cpu_64b_w.user : '0) |
        ((io_64b_w_sel_mem1 && io_64b_wvalid) ? io_64b_w.user : '0) |
        ((acc_64b_w_sel_mem1 && acc_64b_wvalid) ? acc_64b_w.user : '0);
    assign mem1_axi_wvalid = (cpu_64b_w_sel_mem1 && cpu_64b_wvalid) || (io_64b_w_sel_mem1 && io_64b_wvalid) || (acc_64b_w_sel_mem1 && acc_64b_wvalid);

    // Bready (slave -> the master whose response arbiter granted it)
    assign mem1_axi_bready = (cpu_64b_b_rgnt_mem1 ? cpu_64b_bready : '0) |
        (io_64b_b_rgnt_mem1 ? io_64b_bready : '0) |
        (acc_64b_b_rgnt_mem1 ? acc_64b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign mem1_axi_bridge_id_aw = (cpu_64b_aw_gnt_mem1 ? cpu_bridge_id_aw : '0) |
        (io_64b_aw_gnt_mem1 ? io_bridge_id_aw : '0) |
        (acc_64b_aw_gnt_mem1 ? acc_bridge_id_aw : '0);

    // AR request slots for mem1: arbitration at the slave pins
    assign cpu_64b_ar_slot_mem1_in_valid = cpu_64b_ar_to_mem1 && cpu_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_cpu_64b_ar_slot_mem1 (
