        .wr_valid(cpu_64b_ar_slot_mem1_in_valid), .wr_ready(cpu_64b_ar_slot_mem1_in_ready), .wr_data(cpu_64b_ar),
        .rd_valid(cpu_64b_ar_slot_mem1_valid), .rd_ready(cpu_64b_ar_slot_mem1_ready), .rd_data(cpu_64b_ar_slot_mem1),
