    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_io_64b_ar_slot_mem1 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(io_64b_ar_slot_mem1_in_valid), .wr_ready(io_64b_ar_slot_mem1_in_ready), .wr_data(io_64b_ar),
        .rd_valid(io_64b_ar_slot_mem1_valid), .rd_ready(io_64b_ar_slot_mem1_ready), .rd_data(io_64b_ar_slot_mem1),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign acc_64b_ar_slot_mem1_in_valid = acc_64b_ar_to_mem1 && acc_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_acc_64b_ar_slot_mem1 (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(acc_64b_ar_slot_mem1_in_valid), .wr_ready(acc_64b_ar_slot_mem1_in_ready), .wr_data(acc_64b_ar),
        .rd_valid(acc_64b_ar_slot_mem1_valid), .rd_ready(acc_64b_ar_slot_mem1_ready), .rd_data(acc_64b_ar_slot_mem1),
