    // ---- AR arbiter for mem1: round-robin, lock until handshake ----
    logic [2:0] mem1_ar_arb_req;
    assign mem1_ar_arb_req = {acc_64b_ar_slot_mem1_valid, io_64b_ar_slot_mem1_valid, cpu_64b_ar_slot_mem1_valid};
    logic [1:0] mem1_ar_arb_lock, mem1_ar_arb_rr;
    logic mem1_ar_arb_locked;
    wire [1:0] mem1_ar_arb_pick = (mem1_ar_arb_rr == 2'd0) ? (mem1_ar_arb_req[0] ? 2'd0 : mem1_ar_arb_req[1] ? 2'd1 : 2'd2) : 
