    wire [1:0] mem1_ar_arb_gnt = mem1_ar_arb_locked ? mem1_ar_arb_lock : mem1_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            mem1_ar_arb_lock   <= '0;
            mem1_ar_arb_rr     <= '0;
            mem1_ar_arb_locked <= 1'b0;
