                mem1_ar_arb_rr <= (mem1_ar_arb_gnt == 2'd2) ? 2'd0 : mem1_ar_arb_gnt + 1'b1;
            end else if (mem1_axi_arvalid) begin
                mem1_ar_arb_lock   <= mem1_ar_arb_gnt;
                mem1_ar_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_64b_ar_gnt_mem1 = mem1_ar_arb_gnt_valid && (mem1_ar_arb_gnt == 2'd0) && mem1_ar_arb_req[0];
    wire io_64b_ar_gnt_mem1 = mem1_ar_arb_gnt_valid && (mem1_ar_arb_gnt == 2'd1) && mem1_ar_arb_req[1];
    wire acc_64b_ar_gnt_mem1 = mem1_ar_arb_gnt_valid && (mem1_ar_arb_gnt == 2'd2) && mem1_ar_arb_req[2];
    assign cpu_64b_ar_slot_mem1_ready = cpu_64b_ar_gnt_mem1 && mem1_axi_arready;
    assign io_64b_ar_slot_mem1_ready = io_64b_ar_gnt_mem1 && mem1_axi_arready;
    assign acc_64b_ar_slot_mem1_ready = acc_64b_ar_gnt_mem1 && mem1_axi_arready;

    // AR channel (arbitrated mux across reading masters)
    assign mem1_axi_arid = (cpu_64b_ar_gnt_mem1 ? cpu_64b_ar_slot_mem1.id : '0) |
        (io_64b_ar_gnt_mem1 ? io_64b_ar_slot_mem1.id : '0) |
        (acc_64b_ar_gnt_mem1 ? acc_64b_ar_slot_mem1.id : '0);
    assign mem1_axi_araddr = (cpu_64b_ar_gnt_mem1 ? cpu_64b_ar_slot_mem1.addr : '0) |
        (io_64b_ar_gnt_mem1 ? io_64b_ar_slot_mem1.addr : '0) |
        (acc_64b_ar_gnt_mem1 ? acc_64b_ar_slot_mem1.addr : '0);
    assign mem1_axi_arlen = (cpu_64b_ar_gnt_mem1 ? cpu_64b_ar_slot_mem1.len : '0) |
        (io_64b_ar_gnt_mem1 ? io_64b_ar_slot_mem1.len : '0) |
        (acc_64b_ar_gnt_mem1 ? acc_64b_ar_slot_mem1.len : '0);
    assign mem1_axi_arsize = (cpu_64b_ar_gnt_mem1 ? cpu_64b_ar_slot_mem1.size : '0) |
        (io_64b_ar_gnt_mem1 ? io_64b_ar_slot_mem1.size : '0) |
        (acc_64b_ar_gnt_mem1 ? acc_64b_ar_slot_mem1.size : '0);
    assign mem1_axi_arburst = (cpu_64b_ar_gnt_mem1 ? cpu_64b_ar_slot_mem1.burst : '0) |
        (io_64b_ar_gnt_mem1 ? io_64b_ar_slot_mem1.burst : '0) |
        (acc_64b_ar_gnt_mem1 ? acc_64b_ar_slot_mem1.burst : '0);
    assign mem1_axi_arlock = (cpu_64b_ar_gnt_mem1 ? cpu_64b_ar_slot_mem1.lock : '0) |
        (io_64b_ar_gnt_mem1 ? io_64b_ar_slot_mem1.lock : '0) |
        (acc_64b_ar_gnt_mem1 ? acc_64b_ar_slot_mem1.lock : '0);
    assign mem1_axi_arcache = (cpu_64b_ar_gnt_mem1 ? cpu_64b_ar_slot_mem1.cache : '0) |
        (io_64b_ar_gnt_mem1 ? io_64b_ar_slot_mem1.cache : '0) |
        (acc_64b_ar_gnt_mem1 ? acc_64b_ar_slot_mem1.cache : '0);
    assign mem1_axi_arprot = (cpu_64b_ar_gnt_mem1 ? cpu_64b_ar_slot_mem1.prot : '0) |
        (io_64b_ar_gnt_mem1 ? io_64b_ar_slot_mem1.prot : '0) |
        (acc_64b_ar_gnt_mem1 ? acc_64b_ar_slot_mem1.prot : '0);
    assign mem1_axi_arqos = (cpu_64b_ar_gnt_mem1 ? cpu_64b_ar_slot_mem1.qos : '0) |
        (io_64b_ar_gnt_mem1 ? io_64b_ar_slot_mem1.qos : '0) |
        (acc_64b_ar_gnt_mem1 ? acc_64b_ar_slot_mem1.qos : '0);
    assign mem1_axi_arregion = (cpu_64b_ar_gnt_mem1 ? cpu_64b_ar_slot_mem1.region : '0) |
        (io_64b_ar_gnt_mem1 ? io_64b_ar_slot_mem1.region : '0) |
        (acc_64b_ar_gnt_mem1 ? acc_64b_ar_slot_mem1.region : '0);
    assign mem1_axi_aruser = (cpu_64b_ar_gnt_mem1 ? cpu_64b_ar_slot_mem1.user : '0) |
        (io_64b_ar_gnt_mem1 ? io_64b_ar_slot_mem1.user : '0) |
        (acc_64b_ar_gnt_mem1 ? acc_64b_ar_slot_mem1.user : '0);
    assign mem1_axi_arvalid = cpu_64b_ar_gnt_mem1 || io_64b_ar_gnt_mem1 || acc_64b_ar_gnt_mem1;

    // Rready (slave -> the master whose response arbiter granted it)
    assign mem1_axi_rready = (cpu_64b_r_rgnt_mem1 ? cpu_64b_rready : '0) |
        (io_64b_r_rgnt_mem1 ? io_64b_rready : '0) |
        (acc_64b_r_rgnt_mem1 ? acc_64b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign mem1_axi_bridge_id_ar = (cpu_64b_ar_gnt_mem1 ? cpu_bridge_id_ar : '0) |
        (io_64b_ar_gnt_mem1 ? io_bridge_id_ar : '0) |
        (acc_64b_ar_gnt_mem1 ? acc_bridge_id_ar : '0);


    // ================================================================
    // Slave 2: mem2 (32b)
    // ================================================================
    // mem2: 3 masters on per-master lanes, arbitrated on mem2's own clock in its slave adapter (bridge W9)
    wire cpu_32b_aw_to_mem2 = ((cpu_32b_aw.addr >= 32'h30000000) && (cpu_32b_aw.addr <= 32'h3fffffff));
    wire cpu_32b_ar_to_mem2 = ((cpu_32b_ar.addr >= 32'h30000000) && (cpu_32b_ar.addr <= 32'h3fffffff));
    wire io_32b_aw_to_mem2 = ((io_32b_aw.addr >= 32'h30000000) && (io_32b_aw.addr <= 32'h3fffffff));
    wire io_32b_ar_to_mem2 = ((io_32b_ar.addr >= 32'h30000000) && (io_32b_ar.addr <= 32'h3fffffff));
    wire acc_32b_aw_to_mem2 = ((acc_32b_aw.addr >= 32'h30000000) && (acc_32b_aw.addr <= 32'h3fffffff));
    wire acc_32b_ar_to_mem2 = ((acc_32b_ar.addr >= 32'h30000000) && (acc_32b_ar.addr <= 32'h3fffffff));
    assign mem2_axi_lane_awvalid[0] = cpu_32b_aw_to_mem2 && !(cpu_32b_aw_hold_mem2 || cpu_32b_wdest_full) && cpu_32b_awvalid;
    assign mem2_axi_lane_aw[0*69 +: 69] = {cpu_32b_aw.id, cpu_32b_aw.addr, cpu_32b_aw.len, cpu_32b_aw.size, cpu_32b_aw.burst, cpu_32b_aw.lock, cpu_32b_aw.cache, cpu_32b_aw.prot, cpu_32b_aw.qos, cpu_32b_aw.region, cpu_32b_aw.user};
    assign cpu_32b_w_sel_mem2 = cpu_32b_w_to_mem2;
    assign mem2_axi_lane_wvalid[0] = cpu_32b_w_to_mem2 && cpu_32b_wvalid;
    assign mem2_axi_lane_w[0*38 +: 38] = {cpu_32b_w.data, cpu_32b_w.strb, cpu_32b_w.last, cpu_32b_w.user};
    assign mem2_axi_lane_arvalid[0] = cpu_32b_ar_to_mem2 && cpu_32b_arvalid;
    assign mem2_axi_lane_ar[0*69 +: 69] = {cpu_32b_ar.id, cpu_32b_ar.addr, cpu_32b_ar.len, cpu_32b_ar.size, cpu_32b_ar.burst, cpu_32b_ar.lock, cpu_32b_ar.cache, cpu_32b_ar.prot, cpu_32b_ar.qos, cpu_32b_ar.region, cpu_32b_ar.user};
    assign mem2_axi_lane_awvalid[1] = io_32b_aw_to_mem2 && !(io_32b_aw_hold_mem2 || io_32b_wdest_full) && io_32b_awvalid;
    assign mem2_axi_lane_aw[1*69 +: 69] = {io_32b_aw.id, io_32b_aw.addr, io_32b_aw.len, io_32b_aw.size, io_32b_aw.burst, io_32b_aw.lock, io_32b_aw.cache, io_32b_aw.prot, io_32b_aw.qos, io_32b_aw.region, io_32b_aw.user};
    assign io_32b_w_sel_mem2 = io_32b_w_to_mem2;
    assign mem2_axi_lane_wvalid[1] = io_32b_w_to_mem2 && io_32b_wvalid;
    assign mem2_axi_lane_w[1*38 +: 38] = {io_32b_w.data, io_32b_w.strb, io_32b_w.last, io_32b_w.user};
    assign mem2_axi_lane_arvalid[1] = io_32b_ar_to_mem2 && io_32b_arvalid;
    assign mem2_axi_lane_ar[1*69 +: 69] = {io_32b_ar.id, io_32b_ar.addr, io_32b_ar.len, io_32b_ar.size, io_32b_ar.burst, io_32b_ar.lock, io_32b_ar.cache, io_32b_ar.prot, io_32b_ar.qos, io_32b_ar.region, io_32b_ar.user};
    assign mem2_axi_lane_awvalid[2] = acc_32b_aw_to_mem2 && !(acc_32b_aw_hold_mem2 || acc_32b_wdest_full) && acc_32b_awvalid;
    assign mem2_axi_lane_aw[2*69 +: 69] = {acc_32b_aw.id, acc_32b_aw.addr, acc_32b_aw.len, acc_32b_aw.size, acc_32b_aw.burst, acc_32b_aw.lock, acc_32b_aw.cache, acc_32b_aw.prot, acc_32b_aw.qos, acc_32b_aw.region, acc_32b_aw.user};
    assign acc_32b_w_sel_mem2 = acc_32b_w_to_mem2;
    assign mem2_axi_lane_wvalid[2] = acc_32b_w_to_mem2 && acc_32b_wvalid;
    assign mem2_axi_lane_w[2*38 +: 38] = {acc_32b_w.data, acc_32b_w.strb, acc_32b_w.last, acc_32b_w.user};
    assign mem2_axi_lane_arvalid[2] = acc_32b_ar_to_mem2 && acc_32b_arvalid;
    assign mem2_axi_lane_ar[2*69 +: 69] = {acc_32b_ar.id, acc_32b_ar.addr, acc_32b_ar.len, acc_32b_ar.size, acc_32b_ar.burst, acc_32b_ar.lock, acc_32b_ar.cache, acc_32b_ar.prot, acc_32b_ar.qos, acc_32b_ar.region, acc_32b_ar.user};
    assign mem2_axi_awid = '0;
    assign mem2_axi_awaddr = '0;
    assign mem2_axi_awlen = '0;
    assign mem2_axi_awsize = '0;
    assign mem2_axi_awburst = '0;
    assign mem2_axi_awlock = '0;
    assign mem2_axi_awcache = '0;
    assign mem2_axi_awprot = '0;
    assign mem2_axi_awqos = '0;
    assign mem2_axi_awregion = '0;
    assign mem2_axi_awuser = '0;
    assign mem2_axi_awvalid = '0;
    assign mem2_axi_wdata = '0;
    assign mem2_axi_wstrb = '0;
    assign mem2_axi_wlast = '0;
    assign mem2_axi_wuser = '0;
    assign mem2_axi_wvalid = '0;
    assign mem2_axi_bridge_id_aw = '0;
    assign mem2_axi_arid = '0;
    assign mem2_axi_araddr = '0;
    assign mem2_axi_arlen = '0;
    assign mem2_axi_arsize = '0;
    assign mem2_axi_arburst = '0;
    assign mem2_axi_arlock = '0;
    assign mem2_axi_arcache = '0;
    assign mem2_axi_arprot = '0;
    assign mem2_axi_arqos = '0;
    assign mem2_axi_arregion = '0;
    assign mem2_axi_aruser = '0;
    assign mem2_axi_arvalid = '0;
    assign mem2_axi_bridge_id_ar = '0;
    assign mem2_axi_bready = (cpu_32b_b_rgnt_mem2 ? cpu_32b_bready : '0) |
        (io_32b_b_rgnt_mem2 ? io_32b_bready : '0) |
        (acc_32b_b_rgnt_mem2 ? acc_32b_bready : '0);
    assign mem2_axi_rready = (cpu_32b_r_rgnt_mem2 ? cpu_32b_rready : '0) |
        (io_32b_r_rgnt_mem2 ? io_32b_rready : '0) |
        (acc_32b_r_rgnt_mem2 ? acc_32b_rready : '0);


    // ================================================================
    // Slave 3: bram (64b)
    // ================================================================
    // Multi-master (5 masters) → bram
    //   - cpu (rw)
    //   - io (rw)
    //   - acc (rw)
    //   - atg (rw)
    //   - cdma (rw)

    wire cpu_64b_aw_to_bram = ((cpu_64b_aw.addr >= 32'h20000000) && (cpu_64b_aw.addr <= 32'h2000ffff));
    wire cpu_64b_ar_to_bram = ((cpu_64b_ar.addr >= 32'h20000000) && (cpu_64b_ar.addr <= 32'h2000ffff));
    wire io_64b_aw_to_bram = ((io_64b_aw.addr >= 32'h20000000) && (io_64b_aw.addr <= 32'h2000ffff));
    wire io_64b_ar_to_bram = ((io_64b_ar.addr >= 32'h20000000) && (io_64b_ar.addr <= 32'h2000ffff));
    wire acc_64b_aw_to_bram = ((acc_64b_aw.addr >= 32'h20000000) && (acc_64b_aw.addr <= 32'h2000ffff));
    wire acc_64b_ar_to_bram = ((acc_64b_ar.addr >= 32'h20000000) && (acc_64b_ar.addr <= 32'h2000ffff));
    wire atg_64b_aw_to_bram = ((atg_64b_aw.addr >= 32'h20000000) && (atg_64b_aw.addr <= 32'h2000ffff));
    wire atg_64b_ar_to_bram = ((atg_64b_ar.addr >= 32'h20000000) && (atg_64b_ar.addr <= 32'h2000ffff));
    wire cdma_64b_aw_to_bram = ((cdma_64b_aw.addr >= 32'h20000000) && (cdma_64b_aw.addr <= 32'h2000ffff));
    wire cdma_64b_ar_to_bram = ((cdma_64b_ar.addr >= 32'h20000000) && (cdma_64b_ar.addr <= 32'h2000ffff));

    // AW request slots for bram: arbitration at the slave pins
    assign cpu_64b_aw_slot_bram_in_valid = cpu_64b_aw_to_bram && cpu_64b_awvalid && !(cpu_64b_aw_hold_bram || (|cpu_32b_wlive_mem2) || cpu_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_cpu_64b_aw_slot_bram (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_64b_aw_slot_bram_in_valid), .wr_ready(cpu_64b_aw_slot_bram_in_ready), .wr_data(cpu_64b_aw),
        .rd_valid(cpu_64b_aw_slot_bram_valid), .rd_ready(cpu_64b_aw_slot_bram_ready), .rd_data(cpu_64b_aw_slot_bram),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign io_64b_aw_slot_bram_in_valid = io_64b_aw_to_bram && io_64b_awvalid && !(io_64b_aw_hold_bram || (|io_32b_wlive_mem2) || io_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_io_64b_aw_slot_bram (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(io_64b_aw_slot_bram_in_valid), .wr_ready(io_64b_aw_slot_bram_in_ready), .wr_data(io_64b_aw),
        .rd_valid(io_64b_aw_slot_bram_valid), .rd_ready(io_64b_aw_slot_bram_ready), .rd_data(io_64b_aw_slot_bram),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign acc_64b_aw_slot_bram_in_valid = acc_64b_aw_to_bram && acc_64b_awvalid && !(acc_64b_aw_hold_bram || (|acc_32b_wlive_mem2) || acc_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_acc_64b_aw_slot_bram (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(acc_64b_aw_slot_bram_in_valid), .wr_ready(acc_64b_aw_slot_bram_in_ready), .wr_data(acc_64b_aw),
        .rd_valid(acc_64b_aw_slot_bram_valid), .rd_ready(acc_64b_aw_slot_bram_ready), .rd_data(acc_64b_aw_slot_bram),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign atg_64b_aw_slot_bram_in_valid = atg_64b_aw_to_bram && atg_64b_awvalid && !(atg_64b_aw_hold_bram || atg_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_atg_64b_aw_slot_bram (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(atg_64b_aw_slot_bram_in_valid), .wr_ready(atg_64b_aw_slot_bram_in_ready), .wr_data(atg_64b_aw),
        .rd_valid(atg_64b_aw_slot_bram_valid), .rd_ready(atg_64b_aw_slot_bram_ready), .rd_data(atg_64b_aw_slot_bram),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign cdma_64b_aw_slot_bram_in_valid = cdma_64b_aw_to_bram && cdma_64b_awvalid && !(cdma_64b_aw_hold_bram || cdma_64b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_cdma_64b_aw_slot_bram (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cdma_64b_aw_slot_bram_in_valid), .wr_ready(cdma_64b_aw_slot_bram_in_ready), .wr_data(cdma_64b_aw),
        .rd_valid(cdma_64b_aw_slot_bram_valid), .rd_ready(cdma_64b_aw_slot_bram_ready), .rd_data(cdma_64b_aw_slot_bram),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AW arbiter for bram: round-robin, lock until handshake ----
    logic [4:0] bram_aw_arb_req;
    assign bram_aw_arb_req = {cdma_64b_aw_slot_bram_valid, atg_64b_aw_slot_bram_valid, acc_64b_aw_slot_bram_valid, io_64b_aw_slot_bram_valid, cpu_64b_aw_slot_bram_valid};
    logic [2:0] bram_aw_arb_lock, bram_aw_arb_rr;
    logic bram_aw_arb_locked;
    wire [2:0] bram_aw_arb_pick = (bram_aw_arb_rr == 3'd0) ? (bram_aw_arb_req[0] ? 3'd0 : bram_aw_arb_req[1] ? 3'd1 : bram_aw_arb_req[2] ? 3'd2 : bram_aw_arb_req[3] ? 3'd3 : 3'd4) : 
        (bram_aw_arb_rr == 3'd1) ? (bram_aw_arb_req[1] ? 3'd1 : bram_aw_arb_req[2] ? 3'd2 : bram_aw_arb_req[3] ? 3'd3 : bram_aw_arb_req[4] ? 3'd4 : 3'd0) : 
        (bram_aw_arb_rr == 3'd2) ? (bram_aw_arb_req[2] ? 3'd2 : bram_aw_arb_req[3] ? 3'd3 : bram_aw_arb_req[4] ? 3'd4 : bram_aw_arb_req[0] ? 3'd0 : 3'd1) : 
        (bram_aw_arb_rr == 3'd3) ? (bram_aw_arb_req[3] ? 3'd3 : bram_aw_arb_req[4] ? 3'd4 : bram_aw_arb_req[0] ? 3'd0 : bram_aw_arb_req[1] ? 3'd1 : 3'd2) : 
        bram_aw_arb_req[4] ? 3'd4 : bram_aw_arb_req[0] ? 3'd0 : bram_aw_arb_req[1] ? 3'd1 : bram_aw_arb_req[2] ? 3'd2 : 3'd3;
    wire bram_aw_arb_gnt_valid = bram_aw_arb_locked || (|bram_aw_arb_req);
    wire [2:0] bram_aw_arb_gnt = bram_aw_arb_locked ? bram_aw_arb_lock : bram_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            bram_aw_arb_lock   <= '0;
            bram_aw_arb_rr     <= '0;
            bram_aw_arb_locked <= 1'b0;
        end else begin
            if (bram_axi_awvalid && bram_axi_awready) begin
                bram_aw_arb_locked <= 1'b0;
                bram_aw_arb_rr <= (bram_aw_arb_gnt == 3'd4) ? 3'd0 : bram_aw_arb_gnt + 1'b1;
            end else if (bram_axi_awvalid) begin
                bram_aw_arb_lock   <= bram_aw_arb_gnt;
                bram_aw_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_64b_aw_gnt_bram = bram_aw_arb_gnt_valid && (bram_aw_arb_gnt == 3'd0) && bram_aw_arb_req[0];
    wire io_64b_aw_gnt_bram = bram_aw_arb_gnt_valid && (bram_aw_arb_gnt == 3'd1) && bram_aw_arb_req[1];
    wire acc_64b_aw_gnt_bram = bram_aw_arb_gnt_valid && (bram_aw_arb_gnt == 3'd2) && bram_aw_arb_req[2];
    wire atg_64b_aw_gnt_bram = bram_aw_arb_gnt_valid && (bram_aw_arb_gnt == 3'd3) && bram_aw_arb_req[3];
    wire cdma_64b_aw_gnt_bram = bram_aw_arb_gnt_valid && (bram_aw_arb_gnt == 3'd4) && bram_aw_arb_req[4];
    assign cpu_64b_aw_slot_bram_ready = cpu_64b_aw_gnt_bram && bram_axi_awready;
    assign io_64b_aw_slot_bram_ready = io_64b_aw_gnt_bram && bram_axi_awready;
    assign acc_64b_aw_slot_bram_ready = acc_64b_aw_gnt_bram && bram_axi_awready;
    assign atg_64b_aw_slot_bram_ready = atg_64b_aw_gnt_bram && bram_axi_awready;
    assign cdma_64b_aw_slot_bram_ready = cdma_64b_aw_gnt_bram && bram_axi_awready;

    // AW channel (arbitrated mux across writing masters)
    assign bram_axi_awid = (cpu_64b_aw_gnt_bram ? cpu_64b_aw_slot_bram.id : '0) |
        (io_64b_aw_gnt_bram ? io_64b_aw_slot_bram.id : '0) |
        (acc_64b_aw_gnt_bram ? acc_64b_aw_slot_bram.id : '0) |
        (atg_64b_aw_gnt_bram ? atg_64b_aw_slot_bram.id : '0) |
        (cdma_64b_aw_gnt_bram ? cdma_64b_aw_slot_bram.id : '0);
    assign bram_axi_awaddr = (cpu_64b_aw_gnt_bram ? cpu_64b_aw_slot_bram.addr : '0) |
        (io_64b_aw_gnt_bram ? io_64b_aw_slot_bram.addr : '0) |
        (acc_64b_aw_gnt_bram ? acc_64b_aw_slot_bram.addr : '0) |
        (atg_64b_aw_gnt_bram ? atg_64b_aw_slot_bram.addr : '0) |
        (cdma_64b_aw_gnt_bram ? cdma_64b_aw_slot_bram.addr : '0);
    assign bram_axi_awlen = (cpu_64b_aw_gnt_bram ? cpu_64b_aw_slot_bram.len : '0) |
        (io_64b_aw_gnt_bram ? io_64b_aw_slot_bram.len : '0) |
        (acc_64b_aw_gnt_bram ? acc_64b_aw_slot_bram.len : '0) |
        (atg_64b_aw_gnt_bram ? atg_64b_aw_slot_bram.len : '0) |
        (cdma_64b_aw_gnt_bram ? cdma_64b_aw_slot_bram.len : '0);
    assign bram_axi_awsize = (cpu_64b_aw_gnt_bram ? cpu_64b_aw_slot_bram.size : '0) |
        (io_64b_aw_gnt_bram ? io_64b_aw_slot_bram.size : '0) |
        (acc_64b_aw_gnt_bram ? acc_64b_aw_slot_bram.size : '0) |
        (atg_64b_aw_gnt_bram ? atg_64b_aw_slot_bram.size : '0) |
        (cdma_64b_aw_gnt_bram ? cdma_64b_aw_slot_bram.size : '0);
    assign bram_axi_awburst = (cpu_64b_aw_gnt_bram ? cpu_64b_aw_slot_bram.burst : '0) |
        (io_64b_aw_gnt_bram ? io_64b_aw_slot_bram.burst : '0) |
        (acc_64b_aw_gnt_bram ? acc_64b_aw_slot_bram.burst : '0) |
        (atg_64b_aw_gnt_bram ? atg_64b_aw_slot_bram.burst : '0) |
        (cdma_64b_aw_gnt_bram ? cdma_64b_aw_slot_bram.burst : '0);
    assign bram_axi_awlock = (cpu_64b_aw_gnt_bram ? cpu_64b_aw_slot_bram.lock : '0) |
        (io_64b_aw_gnt_bram ? io_64b_aw_slot_bram.lock : '0) |
        (acc_64b_aw_gnt_bram ? acc_64b_aw_slot_bram.lock : '0) |
        (atg_64b_aw_gnt_bram ? atg_64b_aw_slot_bram.lock : '0) |
        (cdma_64b_aw_gnt_bram ? cdma_64b_aw_slot_bram.lock : '0);
    assign bram_axi_awcache = (cpu_64b_aw_gnt_bram ? cpu_64b_aw_slot_bram.cache : '0) |
        (io_64b_aw_gnt_bram ? io_64b_aw_slot_bram.cache : '0) |
        (acc_64b_aw_gnt_bram ? acc_64b_aw_slot_bram.cache : '0) |
        (atg_64b_aw_gnt_bram ? atg_64b_aw_slot_bram.cache : '0) |
        (cdma_64b_aw_gnt_bram ? cdma_64b_aw_slot_bram.cache : '0);
    assign bram_axi_awprot = (cpu_64b_aw_gnt_bram ? cpu_64b_aw_slot_bram.prot : '0) |
        (io_64b_aw_gnt_bram ? io_64b_aw_slot_bram.prot : '0) |
        (acc_64b_aw_gnt_bram ? acc_64b_aw_slot_bram.prot : '0) |
        (atg_64b_aw_gnt_bram ? atg_64b_aw_slot_bram.prot : '0) |
        (cdma_64b_aw_gnt_bram ? cdma_64b_aw_slot_bram.prot : '0);
    assign bram_axi_awqos = (cpu_64b_aw_gnt_bram ? cpu_64b_aw_slot_bram.qos : '0) |
        (io_64b_aw_gnt_bram ? io_64b_aw_slot_bram.qos : '0) |
        (acc_64b_aw_gnt_bram ? acc_64b_aw_slot_bram.qos : '0) |
        (atg_64b_aw_gnt_bram ? atg_64b_aw_slot_bram.qos : '0) |
        (cdma_64b_aw_gnt_bram ? cdma_64b_aw_slot_bram.qos : '0);
    assign bram_axi_awregion = (cpu_64b_aw_gnt_bram ? cpu_64b_aw_slot_bram.region : '0) |
        (io_64b_aw_gnt_bram ? io_64b_aw_slot_bram.region : '0) |
        (acc_64b_aw_gnt_bram ? acc_64b_aw_slot_bram.region : '0) |
        (atg_64b_aw_gnt_bram ? atg_64b_aw_slot_bram.region : '0) |
        (cdma_64b_aw_gnt_bram ? cdma_64b_aw_slot_bram.region : '0);
    assign bram_axi_awuser = (cpu_64b_aw_gnt_bram ? cpu_64b_aw_slot_bram.user : '0) |
        (io_64b_aw_gnt_bram ? io_64b_aw_slot_bram.user : '0) |
        (acc_64b_aw_gnt_bram ? acc_64b_aw_slot_bram.user : '0) |
        (atg_64b_aw_gnt_bram ? atg_64b_aw_slot_bram.user : '0) |
        (cdma_64b_aw_gnt_bram ? cdma_64b_aw_slot_bram.user : '0);
    assign bram_axi_awvalid = cpu_64b_aw_gnt_bram || io_64b_aw_gnt_bram || acc_64b_aw_gnt_bram || atg_64b_aw_gnt_bram || cdma_64b_aw_gnt_bram;

    // W owner FIFO: slave-side AW pick order owns the W channel
    // (16 deep: max_outstanding 16)
    logic [2:0] bram_wowner_mem [16];
    logic [4:0] bram_wowner_wptr, bram_wowner_rptr;
    logic bram_wowner_ahead;
    wire bram_wowner_valid = (bram_wowner_wptr != bram_wowner_rptr);
    wire bram_wowner_byp = !bram_wowner_valid && !bram_wowner_ahead && bram_axi_awvalid;
    wire bram_wowner_aw_hs = bram_axi_awvalid && bram_axi_awready;
    wire bram_wowner_w_end = bram_axi_wvalid && bram_axi_wready && bram_axi_wlast;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            bram_wowner_wptr  <= '0;
            bram_wowner_rptr  <= '0;
            bram_wowner_ahead <= 1'b0;
        end else begin
            if (bram_wowner_aw_hs && bram_wowner_ahead) begin
                bram_wowner_ahead <= 1'b0;   // its W already went
            end else if (bram_wowner_aw_hs && !(bram_wowner_byp && bram_wowner_w_end)) begin
                bram_wowner_mem[bram_wowner_wptr[3:0]] <= bram_aw_arb_gnt;
                bram_wowner_wptr <= bram_wowner_wptr + 1'b1;
            end else if (!bram_wowner_aw_hs && bram_wowner_byp && bram_wowner_w_end) begin
                bram_wowner_ahead <= 1'b1;
            end
            if (bram_wowner_valid && bram_wowner_w_end) begin
                bram_wowner_rptr <= bram_wowner_rptr + 1'b1;
            end
        end
    )
    wire [2:0] bram_wowner_head = bram_wowner_valid ? bram_wowner_mem[bram_wowner_rptr[3:0]]
                                       : bram_aw_arb_gnt;
    assign cpu_64b_w_sel_bram = (bram_wowner_valid || bram_wowner_byp) && (bram_wowner_head == 3'd0) && cpu_64b_w_to_bram;
    assign io_64b_w_sel_bram = (bram_wowner_valid || bram_wowner_byp) && (bram_wowner_head == 3'd1) && io_64b_w_to_bram;
    assign acc_64b_w_sel_bram = (bram_wowner_valid || bram_wowner_byp) && (bram_wowner_head == 3'd2) && acc_64b_w_to_bram;
    assign atg_64b_w_sel_bram = (bram_wowner_valid || bram_wowner_byp) && (bram_wowner_head == 3'd3) && atg_64b_w_to_bram;
    assign cdma_64b_w_sel_bram = (bram_wowner_valid || bram_wowner_byp) && (bram_wowner_head == 3'd4) && cdma_64b_w_to_bram;

    // W channel (owner-gated mux across writing masters)
    assign bram_axi_wdata = ((cpu_64b_w_sel_bram && cpu_64b_wvalid) ? cpu_64b_w.data : '0) |
        ((io_64b_w_sel_bram && io_64b_wvalid) ? io_64b_w.data : '0) |
        ((acc_64b_w_sel_bram && acc_64b_wvalid) ? acc_64b_w.data : '0) |
        ((atg_64b_w_sel_bram && atg_64b_wvalid) ? atg_64b_w.data : '0) |
        ((cdma_64b_w_sel_bram && cdma_64b_wvalid) ? cdma_64b_w.data : '0);
    assign bram_axi_wstrb = ((cpu_64b_w_sel_bram && cpu_64b_wvalid) ? cpu_64b_w.strb : '0) |
        ((io_64b_w_sel_bram && io_64b_wvalid) ? io_64b_w.strb : '0) |
        ((acc_64b_w_sel_bram && acc_64b_wvalid) ? acc_64b_w.strb : '0) |
        ((atg_64b_w_sel_bram && atg_64b_wvalid) ? atg_64b_w.strb : '0) |
        ((cdma_64b_w_sel_bram && cdma_64b_wvalid) ? cdma_64b_w.strb : '0);
    assign bram_axi_wlast = ((cpu_64b_w_sel_bram && cpu_64b_wvalid) ? cpu_64b_w.last : '0) |
        ((io_64b_w_sel_bram && io_64b_wvalid) ? io_64b_w.last : '0) |
        ((acc_64b_w_sel_bram && acc_64b_wvalid) ? acc_64b_w.last : '0) |
        ((atg_64b_w_sel_bram && atg_64b_wvalid) ? atg_64b_w.last : '0) |
        ((cdma_64b_w_sel_bram && cdma_64b_wvalid) ? cdma_64b_w.last : '0);
    assign bram_axi_wuser = ((cpu_64b_w_sel_bram && cpu_64b_wvalid) ? cpu_64b_w.user : '0) |
        ((io_64b_w_sel_bram && io_64b_wvalid) ? io_64b_w.user : '0) |
        ((acc_64b_w_sel_bram && acc_64b_wvalid) ? acc_64b_w.user : '0) |
        ((atg_64b_w_sel_bram && atg_64b_wvalid) ? atg_64b_w.user : '0) |
        ((cdma_64b_w_sel_bram && cdma_64b_wvalid) ? cdma_64b_w.user : '0);
    assign bram_axi_wvalid = (cpu_64b_w_sel_bram && cpu_64b_wvalid) || (io_64b_w_sel_bram && io_64b_wvalid) || (acc_64b_w_sel_bram && acc_64b_wvalid) || (atg_64b_w_sel_bram && atg_64b_wvalid) || (cdma_64b_w_sel_bram && cdma_64b_wvalid);

    // Bready (slave -> the master whose response arbiter granted it)
    assign bram_axi_bready = (cpu_64b_b_rgnt_bram ? cpu_64b_bready : '0) |
        (io_64b_b_rgnt_bram ? io_64b_bready : '0) |
        (acc_64b_b_rgnt_bram ? acc_64b_bready : '0) |
        (atg_64b_b_rgnt_bram ? atg_64b_bready : '0) |
        (cdma_64b_b_rgnt_bram ? cdma_64b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign bram_axi_bridge_id_aw = (cpu_64b_aw_gnt_bram ? cpu_bridge_id_aw : '0) |
        (io_64b_aw_gnt_bram ? io_bridge_id_aw : '0) |
        (acc_64b_aw_gnt_bram ? acc_bridge_id_aw : '0) |
        (atg_64b_aw_gnt_bram ? atg_bridge_id_aw : '0) |
        (cdma_64b_aw_gnt_bram ? cdma_bridge_id_aw : '0);

    // AR request slots for bram: arbitration at the slave pins
    assign cpu_64b_ar_slot_bram_in_valid = cpu_64b_ar_to_bram && cpu_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_cpu_64b_ar_slot_bram (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_64b_ar_slot_bram_in_valid), .wr_ready(cpu_64b_ar_slot_bram_in_ready), .wr_data(cpu_64b_ar),
        .rd_valid(cpu_64b_ar_slot_bram_valid), .rd_ready(cpu_64b_ar_slot_bram_ready), .rd_data(cpu_64b_ar_slot_bram),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign io_64b_ar_slot_bram_in_valid = io_64b_ar_to_bram && io_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_io_64b_ar_slot_bram (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(io_64b_ar_slot_bram_in_valid), .wr_ready(io_64b_ar_slot_bram_in_ready), .wr_data(io_64b_ar),
        .rd_valid(io_64b_ar_slot_bram_valid), .rd_ready(io_64b_ar_slot_bram_ready), .rd_data(io_64b_ar_slot_bram),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign acc_64b_ar_slot_bram_in_valid = acc_64b_ar_to_bram && acc_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_acc_64b_ar_slot_bram (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(acc_64b_ar_slot_bram_in_valid), .wr_ready(acc_64b_ar_slot_bram_in_ready), .wr_data(acc_64b_ar),
        .rd_valid(acc_64b_ar_slot_bram_valid), .rd_ready(acc_64b_ar_slot_bram_ready), .rd_data(acc_64b_ar_slot_bram),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign atg_64b_ar_slot_bram_in_valid = atg_64b_ar_to_bram && atg_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_atg_64b_ar_slot_bram (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(atg_64b_ar_slot_bram_in_valid), .wr_ready(atg_64b_ar_slot_bram_in_ready), .wr_data(atg_64b_ar),
        .rd_valid(atg_64b_ar_slot_bram_valid), .rd_ready(atg_64b_ar_slot_bram_ready), .rd_data(atg_64b_ar_slot_bram),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign cdma_64b_ar_slot_bram_in_valid = cdma_64b_ar_to_bram && cdma_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_cdma_64b_ar_slot_bram (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cdma_64b_ar_slot_bram_in_valid), .wr_ready(cdma_64b_ar_slot_bram_in_ready), .wr_data(cdma_64b_ar),
        .rd_valid(cdma_64b_ar_slot_bram_valid), .rd_ready(cdma_64b_ar_slot_bram_ready), .rd_data(cdma_64b_ar_slot_bram),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AR arbiter for bram: round-robin, lock until handshake ----
    logic [4:0] bram_ar_arb_req;
    assign bram_ar_arb_req = {cdma_64b_ar_slot_bram_valid, atg_64b_ar_slot_bram_valid, acc_64b_ar_slot_bram_valid, io_64b_ar_slot_bram_valid, cpu_64b_ar_slot_bram_valid};
    logic [2:0] bram_ar_arb_lock, bram_ar_arb_rr;
    logic bram_ar_arb_locked;
    wire [2:0] bram_ar_arb_pick = (bram_ar_arb_rr == 3'd0) ? (bram_ar_arb_req[0] ? 3'd0 : bram_ar_arb_req[1] ? 3'd1 : bram_ar_arb_req[2] ? 3'd2 : bram_ar_arb_req[3] ? 3'd3 : 3'd4) : 
        (bram_ar_arb_rr == 3'd1) ? (bram_ar_arb_req[1] ? 3'd1 : bram_ar_arb_req[2] ? 3'd2 : bram_ar_arb_req[3] ? 3'd3 : bram_ar_arb_req[4] ? 3'd4 : 3'd0) : 
        (bram_ar_arb_rr == 3'd2) ? (bram_ar_arb_req[2] ? 3'd2 : bram_ar_arb_req[3] ? 3'd3 : bram_ar_arb_req[4] ? 3'd4 : bram_ar_arb_req[0] ? 3'd0 : 3'd1) : 
        (bram_ar_arb_rr == 3'd3) ? (bram_ar_arb_req[3] ? 3'd3 : bram_ar_arb_req[4] ? 3'd4 : bram_ar_arb_req[0] ? 3'd0 : bram_ar_arb_req[1] ? 3'd1 : 3'd2) : 
        bram_ar_arb_req[4] ? 3'd4 : bram_ar_arb_req[0] ? 3'd0 : bram_ar_arb_req[1] ? 3'd1 : bram_ar_arb_req[2] ? 3'd2 : 3'd3;
    wire bram_ar_arb_gnt_valid = bram_ar_arb_locked || (|bram_ar_arb_req);
    wire [2:0] bram_ar_arb_gnt = bram_ar_arb_locked ? bram_ar_arb_lock : bram_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            bram_ar_arb_lock   <= '0;
            bram_ar_arb_rr     <= '0;
            bram_ar_arb_locked <= 1'b0;
        end else begin
            if (bram_axi_arvalid && bram_axi_arready) begin
                bram_ar_arb_locked <= 1'b0;
                bram_ar_arb_rr <= (bram_ar_arb_gnt == 3'd4) ? 3'd0 : bram_ar_arb_gnt + 1'b1;
            end else if (bram_axi_arvalid) begin
                bram_ar_arb_lock   <= bram_ar_arb_gnt;
                bram_ar_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_64b_ar_gnt_bram = bram_ar_arb_gnt_valid && (bram_ar_arb_gnt == 3'd0) && bram_ar_arb_req[0];
    wire io_64b_ar_gnt_bram = bram_ar_arb_gnt_valid && (bram_ar_arb_gnt == 3'd1) && bram_ar_arb_req[1];
    wire acc_64b_ar_gnt_bram = bram_ar_arb_gnt_valid && (bram_ar_arb_gnt == 3'd2) && bram_ar_arb_req[2];
    wire atg_64b_ar_gnt_bram = bram_ar_arb_gnt_valid && (bram_ar_arb_gnt == 3'd3) && bram_ar_arb_req[3];
    wire cdma_64b_ar_gnt_bram = bram_ar_arb_gnt_valid && (bram_ar_arb_gnt == 3'd4) && bram_ar_arb_req[4];
    assign cpu_64b_ar_slot_bram_ready = cpu_64b_ar_gnt_bram && bram_axi_arready;
    assign io_64b_ar_slot_bram_ready = io_64b_ar_gnt_bram && bram_axi_arready;
    assign acc_64b_ar_slot_bram_ready = acc_64b_ar_gnt_bram && bram_axi_arready;
    assign atg_64b_ar_slot_bram_ready = atg_64b_ar_gnt_bram && bram_axi_arready;
    assign cdma_64b_ar_slot_bram_ready = cdma_64b_ar_gnt_bram && bram_axi_arready;

    // AR channel (arbitrated mux across reading masters)
    assign bram_axi_arid = (cpu_64b_ar_gnt_bram ? cpu_64b_ar_slot_bram.id : '0) |
        (io_64b_ar_gnt_bram ? io_64b_ar_slot_bram.id : '0) |
        (acc_64b_ar_gnt_bram ? acc_64b_ar_slot_bram.id : '0) |
        (atg_64b_ar_gnt_bram ? atg_64b_ar_slot_bram.id : '0) |
        (cdma_64b_ar_gnt_bram ? cdma_64b_ar_slot_bram.id : '0);
    assign bram_axi_araddr = (cpu_64b_ar_gnt_bram ? cpu_64b_ar_slot_bram.addr : '0) |
        (io_64b_ar_gnt_bram ? io_64b_ar_slot_bram.addr : '0) |
        (acc_64b_ar_gnt_bram ? acc_64b_ar_slot_bram.addr : '0) |
        (atg_64b_ar_gnt_bram ? atg_64b_ar_slot_bram.addr : '0) |
        (cdma_64b_ar_gnt_bram ? cdma_64b_ar_slot_bram.addr : '0);
    assign bram_axi_arlen = (cpu_64b_ar_gnt_bram ? cpu_64b_ar_slot_bram.len : '0) |
        (io_64b_ar_gnt_bram ? io_64b_ar_slot_bram.len : '0) |
        (acc_64b_ar_gnt_bram ? acc_64b_ar_slot_bram.len : '0) |
        (atg_64b_ar_gnt_bram ? atg_64b_ar_slot_bram.len : '0) |
        (cdma_64b_ar_gnt_bram ? cdma_64b_ar_slot_bram.len : '0);
    assign bram_axi_arsize = (cpu_64b_ar_gnt_bram ? cpu_64b_ar_slot_bram.size : '0) |
        (io_64b_ar_gnt_bram ? io_64b_ar_slot_bram.size : '0) |
        (acc_64b_ar_gnt_bram ? acc_64b_ar_slot_bram.size : '0) |
        (atg_64b_ar_gnt_bram ? atg_64b_ar_slot_bram.size : '0) |
        (cdma_64b_ar_gnt_bram ? cdma_64b_ar_slot_bram.size : '0);
    assign bram_axi_arburst = (cpu_64b_ar_gnt_bram ? cpu_64b_ar_slot_bram.burst : '0) |
        (io_64b_ar_gnt_bram ? io_64b_ar_slot_bram.burst : '0) |
        (acc_64b_ar_gnt_bram ? acc_64b_ar_slot_bram.burst : '0) |
        (atg_64b_ar_gnt_bram ? atg_64b_ar_slot_bram.burst : '0) |
        (cdma_64b_ar_gnt_bram ? cdma_64b_ar_slot_bram.burst : '0);
    assign bram_axi_arlock = (cpu_64b_ar_gnt_bram ? cpu_64b_ar_slot_bram.lock : '0) |
        (io_64b_ar_gnt_bram ? io_64b_ar_slot_bram.lock : '0) |
        (acc_64b_ar_gnt_bram ? acc_64b_ar_slot_bram.lock : '0) |
        (atg_64b_ar_gnt_bram ? atg_64b_ar_slot_bram.lock : '0) |
        (cdma_64b_ar_gnt_bram ? cdma_64b_ar_slot_bram.lock : '0);
    assign bram_axi_arcache = (cpu_64b_ar_gnt_bram ? cpu_64b_ar_slot_bram.cache : '0) |
        (io_64b_ar_gnt_bram ? io_64b_ar_slot_bram.cache : '0) |
        (acc_64b_ar_gnt_bram ? acc_64b_ar_slot_bram.cache : '0) |
        (atg_64b_ar_gnt_bram ? atg_64b_ar_slot_bram.cache : '0) |
        (cdma_64b_ar_gnt_bram ? cdma_64b_ar_slot_bram.cache : '0);
    assign bram_axi_arprot = (cpu_64b_ar_gnt_bram ? cpu_64b_ar_slot_bram.prot : '0) |
        (io_64b_ar_gnt_bram ? io_64b_ar_slot_bram.prot : '0) |
        (acc_64b_ar_gnt_bram ? acc_64b_ar_slot_bram.prot : '0) |
        (atg_64b_ar_gnt_bram ? atg_64b_ar_slot_bram.prot : '0) |
        (cdma_64b_ar_gnt_bram ? cdma_64b_ar_slot_bram.prot : '0);
    assign bram_axi_arqos = (cpu_64b_ar_gnt_bram ? cpu_64b_ar_slot_bram.qos : '0) |
        (io_64b_ar_gnt_bram ? io_64b_ar_slot_bram.qos : '0) |
        (acc_64b_ar_gnt_bram ? acc_64b_ar_slot_bram.qos : '0) |
        (atg_64b_ar_gnt_bram ? atg_64b_ar_slot_bram.qos : '0) |
        (cdma_64b_ar_gnt_bram ? cdma_64b_ar_slot_bram.qos : '0);
    assign bram_axi_arregion = (cpu_64b_ar_gnt_bram ? cpu_64b_ar_slot_bram.region : '0) |
        (io_64b_ar_gnt_bram ? io_64b_ar_slot_bram.region : '0) |
        (acc_64b_ar_gnt_bram ? acc_64b_ar_slot_bram.region : '0) |
        (atg_64b_ar_gnt_bram ? atg_64b_ar_slot_bram.region : '0) |
        (cdma_64b_ar_gnt_bram ? cdma_64b_ar_slot_bram.region : '0);
    assign bram_axi_aruser = (cpu_64b_ar_gnt_bram ? cpu_64b_ar_slot_bram.user : '0) |
        (io_64b_ar_gnt_bram ? io_64b_ar_slot_bram.user : '0) |
        (acc_64b_ar_gnt_bram ? acc_64b_ar_slot_bram.user : '0) |
        (atg_64b_ar_gnt_bram ? atg_64b_ar_slot_bram.user : '0) |
        (cdma_64b_ar_gnt_bram ? cdma_64b_ar_slot_bram.user : '0);
    assign bram_axi_arvalid = cpu_64b_ar_gnt_bram || io_64b_ar_gnt_bram || acc_64b_ar_gnt_bram || atg_64b_ar_gnt_bram || cdma_64b_ar_gnt_bram;

    // Rready (slave -> the master whose response arbiter granted it)
    assign bram_axi_rready = (cpu_64b_r_rgnt_bram ? cpu_64b_rready : '0) |
        (io_64b_r_rgnt_bram ? io_64b_rready : '0) |
        (acc_64b_r_rgnt_bram ? acc_64b_rready : '0) |
        (atg_64b_r_rgnt_bram ? atg_64b_rready : '0) |
        (cdma_64b_r_rgnt_bram ? cdma_64b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign bram_axi_bridge_id_ar = (cpu_64b_ar_gnt_bram ? cpu_bridge_id_ar : '0) |
        (io_64b_ar_gnt_bram ? io_bridge_id_ar : '0) |
        (acc_64b_ar_gnt_bram ? acc_bridge_id_ar : '0) |
        (atg_64b_ar_gnt_bram ? atg_bridge_id_ar : '0) |
        (cdma_64b_ar_gnt_bram ? cdma_bridge_id_ar : '0);


    // ================================================================
    // Slave 4: ddr (128b)
    // ================================================================
    // Multi-master (5 masters) → ddr
    //   - cpu (rw)
    //   - io (rw)
    //   - acc (rw)
    //   - atg (rw)
    //   - cdma (rw)

    wire cpu_128b_aw_to_ddr = ((cpu_128b_aw.addr >= 32'h40000000) && (cpu_128b_aw.addr <= 32'h7fffffff));
    wire cpu_128b_ar_to_ddr = ((cpu_128b_ar.addr >= 32'h40000000) && (cpu_128b_ar.addr <= 32'h7fffffff));
    wire io_128b_aw_to_ddr = ((io_128b_aw.addr >= 32'h40000000) && (io_128b_aw.addr <= 32'h7fffffff));
    wire io_128b_ar_to_ddr = ((io_128b_ar.addr >= 32'h40000000) && (io_128b_ar.addr <= 32'h7fffffff));
    wire acc_128b_aw_to_ddr = ((acc_128b_aw.addr >= 32'h40000000) && (acc_128b_aw.addr <= 32'h7fffffff));
    wire acc_128b_ar_to_ddr = ((acc_128b_ar.addr >= 32'h40000000) && (acc_128b_ar.addr <= 32'h7fffffff));
    wire atg_128b_aw_to_ddr = ((atg_128b_aw.addr >= 32'h40000000) && (atg_128b_aw.addr <= 32'h7fffffff));
    wire atg_128b_ar_to_ddr = ((atg_128b_ar.addr >= 32'h40000000) && (atg_128b_ar.addr <= 32'h7fffffff));
    wire cdma_128b_aw_to_ddr = ((cdma_128b_aw.addr >= 32'h40000000) && (cdma_128b_aw.addr <= 32'h7fffffff));
    wire cdma_128b_ar_to_ddr = ((cdma_128b_ar.addr >= 32'h40000000) && (cdma_128b_ar.addr <= 32'h7fffffff));

    // AW request slots for ddr: arbitration at the slave pins
    assign cpu_128b_aw_slot_ddr_in_valid = cpu_128b_aw_to_ddr && cpu_128b_awvalid && !(cpu_128b_aw_hold_ddr || (|cpu_32b_wlive_mem2) || cpu_128b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_cpu_128b_aw_slot_ddr (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_128b_aw_slot_ddr_in_valid), .wr_ready(cpu_128b_aw_slot_ddr_in_ready), .wr_data(cpu_128b_aw),
        .rd_valid(cpu_128b_aw_slot_ddr_valid), .rd_ready(cpu_128b_aw_slot_ddr_ready), .rd_data(cpu_128b_aw_slot_ddr),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign io_128b_aw_slot_ddr_in_valid = io_128b_aw_to_ddr && io_128b_awvalid && !(io_128b_aw_hold_ddr || (|io_32b_wlive_mem2) || io_128b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_io_128b_aw_slot_ddr (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(io_128b_aw_slot_ddr_in_valid), .wr_ready(io_128b_aw_slot_ddr_in_ready), .wr_data(io_128b_aw),
        .rd_valid(io_128b_aw_slot_ddr_valid), .rd_ready(io_128b_aw_slot_ddr_ready), .rd_data(io_128b_aw_slot_ddr),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign acc_128b_aw_slot_ddr_in_valid = acc_128b_aw_to_ddr && acc_128b_awvalid && !(acc_128b_aw_hold_ddr || (|acc_32b_wlive_mem2) || acc_128b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_acc_128b_aw_slot_ddr (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(acc_128b_aw_slot_ddr_in_valid), .wr_ready(acc_128b_aw_slot_ddr_in_ready), .wr_data(acc_128b_aw),
        .rd_valid(acc_128b_aw_slot_ddr_valid), .rd_ready(acc_128b_aw_slot_ddr_ready), .rd_data(acc_128b_aw_slot_ddr),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign atg_128b_aw_slot_ddr_in_valid = atg_128b_aw_to_ddr && atg_128b_awvalid && !(atg_128b_aw_hold_ddr || atg_128b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_atg_128b_aw_slot_ddr (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(atg_128b_aw_slot_ddr_in_valid), .wr_ready(atg_128b_aw_slot_ddr_in_ready), .wr_data(atg_128b_aw),
        .rd_valid(atg_128b_aw_slot_ddr_valid), .rd_ready(atg_128b_aw_slot_ddr_ready), .rd_data(atg_128b_aw_slot_ddr),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign cdma_128b_aw_slot_ddr_in_valid = cdma_128b_aw_to_ddr && cdma_128b_awvalid && !(cdma_128b_aw_hold_ddr || cdma_128b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_cdma_128b_aw_slot_ddr (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cdma_128b_aw_slot_ddr_in_valid), .wr_ready(cdma_128b_aw_slot_ddr_in_ready), .wr_data(cdma_128b_aw),
        .rd_valid(cdma_128b_aw_slot_ddr_valid), .rd_ready(cdma_128b_aw_slot_ddr_ready), .rd_data(cdma_128b_aw_slot_ddr),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AW arbiter for ddr: round-robin, lock until handshake ----
    logic [4:0] ddr_aw_arb_req;
    assign ddr_aw_arb_req = {cdma_128b_aw_slot_ddr_valid, atg_128b_aw_slot_ddr_valid, acc_128b_aw_slot_ddr_valid, io_128b_aw_slot_ddr_valid, cpu_128b_aw_slot_ddr_valid};
    logic [2:0] ddr_aw_arb_lock, ddr_aw_arb_rr;
    logic ddr_aw_arb_locked;
    wire [2:0] ddr_aw_arb_pick = (ddr_aw_arb_rr == 3'd0) ? (ddr_aw_arb_req[0] ? 3'd0 : ddr_aw_arb_req[1] ? 3'd1 : ddr_aw_arb_req[2] ? 3'd2 : ddr_aw_arb_req[3] ? 3'd3 : 3'd4) : 
        (ddr_aw_arb_rr == 3'd1) ? (ddr_aw_arb_req[1] ? 3'd1 : ddr_aw_arb_req[2] ? 3'd2 : ddr_aw_arb_req[3] ? 3'd3 : ddr_aw_arb_req[4] ? 3'd4 : 3'd0) : 
        (ddr_aw_arb_rr == 3'd2) ? (ddr_aw_arb_req[2] ? 3'd2 : ddr_aw_arb_req[3] ? 3'd3 : ddr_aw_arb_req[4] ? 3'd4 : ddr_aw_arb_req[0] ? 3'd0 : 3'd1) : 
        (ddr_aw_arb_rr == 3'd3) ? (ddr_aw_arb_req[3] ? 3'd3 : ddr_aw_arb_req[4] ? 3'd4 : ddr_aw_arb_req[0] ? 3'd0 : ddr_aw_arb_req[1] ? 3'd1 : 3'd2) : 
        ddr_aw_arb_req[4] ? 3'd4 : ddr_aw_arb_req[0] ? 3'd0 : ddr_aw_arb_req[1] ? 3'd1 : ddr_aw_arb_req[2] ? 3'd2 : 3'd3;
    wire ddr_aw_arb_gnt_valid = ddr_aw_arb_locked || (|ddr_aw_arb_req);
    wire [2:0] ddr_aw_arb_gnt = ddr_aw_arb_locked ? ddr_aw_arb_lock : ddr_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            ddr_aw_arb_lock   <= '0;
            ddr_aw_arb_rr     <= '0;
            ddr_aw_arb_locked <= 1'b0;
        end else begin
            if (ddr_axi_awvalid && ddr_axi_awready) begin
                ddr_aw_arb_locked <= 1'b0;
                ddr_aw_arb_rr <= (ddr_aw_arb_gnt == 3'd4) ? 3'd0 : ddr_aw_arb_gnt + 1'b1;
            end else if (ddr_axi_awvalid) begin
                ddr_aw_arb_lock   <= ddr_aw_arb_gnt;
                ddr_aw_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_128b_aw_gnt_ddr = ddr_aw_arb_gnt_valid && (ddr_aw_arb_gnt == 3'd0) && ddr_aw_arb_req[0];
    wire io_128b_aw_gnt_ddr = ddr_aw_arb_gnt_valid && (ddr_aw_arb_gnt == 3'd1) && ddr_aw_arb_req[1];
    wire acc_128b_aw_gnt_ddr = ddr_aw_arb_gnt_valid && (ddr_aw_arb_gnt == 3'd2) && ddr_aw_arb_req[2];
    wire atg_128b_aw_gnt_ddr = ddr_aw_arb_gnt_valid && (ddr_aw_arb_gnt == 3'd3) && ddr_aw_arb_req[3];
    wire cdma_128b_aw_gnt_ddr = ddr_aw_arb_gnt_valid && (ddr_aw_arb_gnt == 3'd4) && ddr_aw_arb_req[4];
    assign cpu_128b_aw_slot_ddr_ready = cpu_128b_aw_gnt_ddr && ddr_axi_awready;
    assign io_128b_aw_slot_ddr_ready = io_128b_aw_gnt_ddr && ddr_axi_awready;
    assign acc_128b_aw_slot_ddr_ready = acc_128b_aw_gnt_ddr && ddr_axi_awready;
    assign atg_128b_aw_slot_ddr_ready = atg_128b_aw_gnt_ddr && ddr_axi_awready;
    assign cdma_128b_aw_slot_ddr_ready = cdma_128b_aw_gnt_ddr && ddr_axi_awready;

    // AW channel (arbitrated mux across writing masters)
    assign ddr_axi_awid = (cpu_128b_aw_gnt_ddr ? cpu_128b_aw_slot_ddr.id : '0) |
        (io_128b_aw_gnt_ddr ? io_128b_aw_slot_ddr.id : '0) |
        (acc_128b_aw_gnt_ddr ? acc_128b_aw_slot_ddr.id : '0) |
        (atg_128b_aw_gnt_ddr ? atg_128b_aw_slot_ddr.id : '0) |
        (cdma_128b_aw_gnt_ddr ? cdma_128b_aw_slot_ddr.id : '0);
    assign ddr_axi_awaddr = (cpu_128b_aw_gnt_ddr ? cpu_128b_aw_slot_ddr.addr : '0) |
        (io_128b_aw_gnt_ddr ? io_128b_aw_slot_ddr.addr : '0) |
        (acc_128b_aw_gnt_ddr ? acc_128b_aw_slot_ddr.addr : '0) |
        (atg_128b_aw_gnt_ddr ? atg_128b_aw_slot_ddr.addr : '0) |
        (cdma_128b_aw_gnt_ddr ? cdma_128b_aw_slot_ddr.addr : '0);
    assign ddr_axi_awlen = (cpu_128b_aw_gnt_ddr ? cpu_128b_aw_slot_ddr.len : '0) |
        (io_128b_aw_gnt_ddr ? io_128b_aw_slot_ddr.len : '0) |
        (acc_128b_aw_gnt_ddr ? acc_128b_aw_slot_ddr.len : '0) |
        (atg_128b_aw_gnt_ddr ? atg_128b_aw_slot_ddr.len : '0) |
        (cdma_128b_aw_gnt_ddr ? cdma_128b_aw_slot_ddr.len : '0);
    assign ddr_axi_awsize = (cpu_128b_aw_gnt_ddr ? cpu_128b_aw_slot_ddr.size : '0) |
        (io_128b_aw_gnt_ddr ? io_128b_aw_slot_ddr.size : '0) |
        (acc_128b_aw_gnt_ddr ? acc_128b_aw_slot_ddr.size : '0) |
        (atg_128b_aw_gnt_ddr ? atg_128b_aw_slot_ddr.size : '0) |
        (cdma_128b_aw_gnt_ddr ? cdma_128b_aw_slot_ddr.size : '0);
    assign ddr_axi_awburst = (cpu_128b_aw_gnt_ddr ? cpu_128b_aw_slot_ddr.burst : '0) |
        (io_128b_aw_gnt_ddr ? io_128b_aw_slot_ddr.burst : '0) |
        (acc_128b_aw_gnt_ddr ? acc_128b_aw_slot_ddr.burst : '0) |
        (atg_128b_aw_gnt_ddr ? atg_128b_aw_slot_ddr.burst : '0) |
        (cdma_128b_aw_gnt_ddr ? cdma_128b_aw_slot_ddr.burst : '0);
    assign ddr_axi_awlock = (cpu_128b_aw_gnt_ddr ? cpu_128b_aw_slot_ddr.lock : '0) |
        (io_128b_aw_gnt_ddr ? io_128b_aw_slot_ddr.lock : '0) |
        (acc_128b_aw_gnt_ddr ? acc_128b_aw_slot_ddr.lock : '0) |
        (atg_128b_aw_gnt_ddr ? atg_128b_aw_slot_ddr.lock : '0) |
        (cdma_128b_aw_gnt_ddr ? cdma_128b_aw_slot_ddr.lock : '0);
    assign ddr_axi_awcache = (cpu_128b_aw_gnt_ddr ? cpu_128b_aw_slot_ddr.cache : '0) |
        (io_128b_aw_gnt_ddr ? io_128b_aw_slot_ddr.cache : '0) |
        (acc_128b_aw_gnt_ddr ? acc_128b_aw_slot_ddr.cache : '0) |
        (atg_128b_aw_gnt_ddr ? atg_128b_aw_slot_ddr.cache : '0) |
        (cdma_128b_aw_gnt_ddr ? cdma_128b_aw_slot_ddr.cache : '0);
    assign ddr_axi_awprot = (cpu_128b_aw_gnt_ddr ? cpu_128b_aw_slot_ddr.prot : '0) |
        (io_128b_aw_gnt_ddr ? io_128b_aw_slot_ddr.prot : '0) |
        (acc_128b_aw_gnt_ddr ? acc_128b_aw_slot_ddr.prot : '0) |
        (atg_128b_aw_gnt_ddr ? atg_128b_aw_slot_ddr.prot : '0) |
        (cdma_128b_aw_gnt_ddr ? cdma_128b_aw_slot_ddr.prot : '0);
    assign ddr_axi_awqos = (cpu_128b_aw_gnt_ddr ? cpu_128b_aw_slot_ddr.qos : '0) |
        (io_128b_aw_gnt_ddr ? io_128b_aw_slot_ddr.qos : '0) |
        (acc_128b_aw_gnt_ddr ? acc_128b_aw_slot_ddr.qos : '0) |
        (atg_128b_aw_gnt_ddr ? atg_128b_aw_slot_ddr.qos : '0) |
        (cdma_128b_aw_gnt_ddr ? cdma_128b_aw_slot_ddr.qos : '0);
    assign ddr_axi_awregion = (cpu_128b_aw_gnt_ddr ? cpu_128b_aw_slot_ddr.region : '0) |
        (io_128b_aw_gnt_ddr ? io_128b_aw_slot_ddr.region : '0) |
        (acc_128b_aw_gnt_ddr ? acc_128b_aw_slot_ddr.region : '0) |
        (atg_128b_aw_gnt_ddr ? atg_128b_aw_slot_ddr.region : '0) |
        (cdma_128b_aw_gnt_ddr ? cdma_128b_aw_slot_ddr.region : '0);
    assign ddr_axi_awuser = (cpu_128b_aw_gnt_ddr ? cpu_128b_aw_slot_ddr.user : '0) |
        (io_128b_aw_gnt_ddr ? io_128b_aw_slot_ddr.user : '0) |
        (acc_128b_aw_gnt_ddr ? acc_128b_aw_slot_ddr.user : '0) |
        (atg_128b_aw_gnt_ddr ? atg_128b_aw_slot_ddr.user : '0) |
        (cdma_128b_aw_gnt_ddr ? cdma_128b_aw_slot_ddr.user : '0);
    assign ddr_axi_awvalid = cpu_128b_aw_gnt_ddr || io_128b_aw_gnt_ddr || acc_128b_aw_gnt_ddr || atg_128b_aw_gnt_ddr || cdma_128b_aw_gnt_ddr;

    // W owner FIFO: slave-side AW pick order owns the W channel
    // (16 deep: max_outstanding 16)
    logic [2:0] ddr_wowner_mem [16];
    logic [4:0] ddr_wowner_wptr, ddr_wowner_rptr;
    logic ddr_wowner_ahead;
    wire ddr_wowner_valid = (ddr_wowner_wptr != ddr_wowner_rptr);
    wire ddr_wowner_byp = !ddr_wowner_valid && !ddr_wowner_ahead && ddr_axi_awvalid;
    wire ddr_wowner_aw_hs = ddr_axi_awvalid && ddr_axi_awready;
    wire ddr_wowner_w_end = ddr_axi_wvalid && ddr_axi_wready && ddr_axi_wlast;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            ddr_wowner_wptr  <= '0;
            ddr_wowner_rptr  <= '0;
            ddr_wowner_ahead <= 1'b0;
        end else begin
            if (ddr_wowner_aw_hs && ddr_wowner_ahead) begin
                ddr_wowner_ahead <= 1'b0;   // its W already went
            end else if (ddr_wowner_aw_hs && !(ddr_wowner_byp && ddr_wowner_w_end)) begin
                ddr_wowner_mem[ddr_wowner_wptr[3:0]] <= ddr_aw_arb_gnt;
                ddr_wowner_wptr <= ddr_wowner_wptr + 1'b1;
            end else if (!ddr_wowner_aw_hs && ddr_wowner_byp && ddr_wowner_w_end) begin
                ddr_wowner_ahead <= 1'b1;
            end
            if (ddr_wowner_valid && ddr_wowner_w_end) begin
                ddr_wowner_rptr <= ddr_wowner_rptr + 1'b1;
            end
        end
    )
    wire [2:0] ddr_wowner_head = ddr_wowner_valid ? ddr_wowner_mem[ddr_wowner_rptr[3:0]]
                                       : ddr_aw_arb_gnt;
    assign cpu_128b_w_sel_ddr = (ddr_wowner_valid || ddr_wowner_byp) && (ddr_wowner_head == 3'd0) && cpu_128b_w_to_ddr;
    assign io_128b_w_sel_ddr = (ddr_wowner_valid || ddr_wowner_byp) && (ddr_wowner_head == 3'd1) && io_128b_w_to_ddr;
    assign acc_128b_w_sel_ddr = (ddr_wowner_valid || ddr_wowner_byp) && (ddr_wowner_head == 3'd2) && acc_128b_w_to_ddr;
