        .rd_valid(io_128b_aw_slot_subtractive_valid), .rd_ready(io_128b_aw_slot_subtractive_ready), .rd_data(io_128b_aw_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
