    );
    assign atg_128b_aw_slot_subtractive_in_valid = atg_128b_aw_to_subtractive && atg_128b_awvalid && !(atg_128b_aw_hold_subtractive || atg_128b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_atg_128b_aw_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(atg_128b_aw_slot_subtractive_in_valid), .wr_ready(atg_128b_aw_slot_subtractive_in_ready), .wr_data(atg_128b_aw),
        .rd_valid(atg_128b_aw_slot_subtractive_valid), .rd_ready(atg_128b_aw_slot_subtractive_ready), .rd_data(atg_128b_aw_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign cdma_128b_aw_slot_subtractive_in_valid = cdma_128b_aw_to_subtractive && cdma_128b_awvalid && !(cdma_128b_aw_hold_subtractive || cdma_128b_wdest_full);
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_aw_t))) u_cdma_128b_aw_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cdma_128b_aw_slot_subtractive_in_valid), .wr_ready(cdma_128b_aw_slot_subtractive_in_ready), .wr_data(cdma_128b_aw),
        .rd_valid(cdma_128b_aw_slot_subtractive_valid), .rd_ready(cdma_128b_aw_slot_subtractive_ready), .rd_data(cdma_128b_aw_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AW arbiter for subtractive: round-robin, lock until handshake ----
    logic [4:0] subtractive_aw_arb_req;
    assign subtractive_aw_arb_req = {cdma_128b_aw_slot_subtractive_valid, atg_128b_aw_slot_subtractive_valid, acc_128b_aw_slot_subtractive_valid, io_128b_aw_slot_subtractive_valid, cpu_128b_aw_slot_subtractive_valid};
    logic [2:0] subtractive_aw_arb_lock, subtractive_aw_arb_rr;
    logic subtractive_aw_arb_locked;
    wire [2:0] subtractive_aw_arb_pick = (subtractive_aw_arb_rr == 3'd0) ? (subtractive_aw_arb_req[0] ? 3'd0 : subtractive_aw_arb_req[1] ? 3'd1 : subtractive_aw_arb_req[2] ? 3'd2 : subtractive_aw_arb_req[3] ? 3'd3 : 3'd4) : 
        (subtractive_aw_arb_rr == 3'd1) ? (subtractive_aw_arb_req[1] ? 3'd1 : subtractive_aw_arb_req[2] ? 3'd2 : subtractive_aw_arb_req[3] ? 3'd3 : subtractive_aw_arb_req[4] ? 3'd4 : 3'd0) : 
        (subtractive_aw_arb_rr == 3'd2) ? (subtractive_aw_arb_req[2] ? 3'd2 : subtractive_aw_arb_req[3] ? 3'd3 : subtractive_aw_arb_req[4] ? 3'd4 : subtractive_aw_arb_req[0] ? 3'd0 : 3'd1) : 
        (subtractive_aw_arb_rr == 3'd3) ? (subtractive_aw_arb_req[3] ? 3'd3 : subtractive_aw_arb_req[4] ? 3'd4 : subtractive_aw_arb_req[0] ? 3'd0 : subtractive_aw_arb_req[1] ? 3'd1 : 3'd2) : 
        subtractive_aw_arb_req[4] ? 3'd4 : subtractive_aw_arb_req[0] ? 3'd0 : subtractive_aw_arb_req[1] ? 3'd1 : subtractive_aw_arb_req[2] ? 3'd2 : 3'd3;
    wire subtractive_aw_arb_gnt_valid = subtractive_aw_arb_locked || (|subtractive_aw_arb_req);
    wire [2:0] subtractive_aw_arb_gnt = subtractive_aw_arb_locked ? subtractive_aw_arb_lock : subtractive_aw_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_aw_arb_lock   <= '0;
            subtractive_aw_arb_rr     <= '0;
            subtractive_aw_arb_locked <= 1'b0;
        end else begin
            if (subtractive_axi_awvalid && subtractive_axi_awready) begin
                subtractive_aw_arb_locked <= 1'b0;
                subtractive_aw_arb_rr <= (subtractive_aw_arb_gnt == 3'd4) ? 3'd0 : subtractive_aw_arb_gnt + 1'b1;
            end else if (subtractive_axi_awvalid) begin
                subtractive_aw_arb_lock   <= subtractive_aw_arb_gnt;
                subtractive_aw_arb_locked <= 1'b1;
