    )
    wire cpu_128b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 3'd0) && subtractive_aw_arb_req[0];
    wire io_128b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 3'd1) && subtractive_aw_arb_req[1];
    wire acc_128b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 3'd2) && subtractive_aw_arb_req[2];
    wire atg_128b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 3'd3) && subtractive_aw_arb_req[3];
    wire cdma_128b_aw_gnt_subtractive = subtractive_aw_arb_gnt_valid && (subtractive_aw_arb_gnt == 3'd4) && subtractive_aw_arb_req[4];
    assign cpu_128b_aw_slot_subtractive_ready = cpu_128b_aw_gnt_subtractive && subtractive_axi_awready;
    assign io_128b_aw_slot_subtractive_ready = io_128b_aw_gnt_subtractive && subtractive_axi_awready;
    assign acc_128b_aw_slot_subtractive_ready = acc_128b_aw_gnt_subtractive && subtractive_axi_awready;
    assign atg_128b_aw_slot_subtractive_ready = atg_128b_aw_gnt_subtractive && subtractive_axi_awready;
    assign cdma_128b_aw_slot_subtractive_ready = cdma_128b_aw_gnt_subtractive && subtractive_axi_awready;

    // AW channel (arbitrated mux across writing masters)
    assign subtractive_axi_awid = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.id : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.id : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.id : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.id : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.id : '0);
    assign subtractive_axi_awaddr = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.addr : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.addr : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.addr : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.addr : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.addr : '0);
    assign subtractive_axi_awlen = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.len : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.len : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.len : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.len : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.len : '0);
    assign subtractive_axi_awsize = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.size : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.size : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.size : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.size : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.size : '0);
    assign subtractive_axi_awburst = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.burst : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.burst : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.burst : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.burst : '0) |
