        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.prot : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.prot : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.prot : '0);
    assign subtractive_axi_awqos = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.qos : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.qos : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.qos : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.qos : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.qos : '0);
    assign subtractive_axi_awregion = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.region : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.region : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.region : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.region : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.region : '0);
    assign subtractive_axi_awuser = (cpu_128b_aw_gnt_subtractive ? cpu_128b_aw_slot_subtractive.user : '0) |
        (io_128b_aw_gnt_subtractive ? io_128b_aw_slot_subtractive.user : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_128b_aw_slot_subtractive.user : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_128b_aw_slot_subtractive.user : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_128b_aw_slot_subtractive.user : '0);
    assign subtractive_axi_awvalid = cpu_128b_aw_gnt_subtractive || io_128b_aw_gnt_subtractive || acc_128b_aw_gnt_subtractive || atg_128b_aw_gnt_subtractive || cdma_128b_aw_gnt_subtractive;

    // W owner FIFO: slave-side AW pick order owns the W channel
    // (16 deep: max_outstanding 16)
    logic [2:0] subtractive_wowner_mem [16];
    logic [4:0] subtractive_wowner_wptr, subtractive_wowner_rptr;
    logic subtractive_wowner_ahead;
    wire subtractive_wowner_valid = (subtractive_wowner_wptr != subtractive_wowner_rptr);
    wire subtractive_wowner_byp = !subtractive_wowner_valid && !subtractive_wowner_ahead && subtractive_axi_awvalid;
    wire subtractive_wowner_aw_hs = subtractive_axi_awvalid && subtractive_axi_awready;
    wire subtractive_wowner_w_end = subtractive_axi_wvalid && subtractive_axi_wready && subtractive_axi_wlast;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_wowner_wptr  <= '0;
            subtractive_wowner_rptr  <= '0;
            subtractive_wowner_ahead <= 1'b0;
        end else begin
            if (subtractive_wowner_aw_hs && subtractive_wowner_ahead) begin
                subtractive_wowner_ahead <= 1'b0;   // its W already went
            end else if (subtractive_wowner_aw_hs && !(subtractive_wowner_byp && subtractive_wowner_w_end)) begin
                subtractive_wowner_mem[subtractive_wowner_wptr[3:0]] <= subtractive_aw_arb_gnt;
                subtractive_wowner_wptr <= subtractive_wowner_wptr + 1'b1;
            end else if (!subtractive_wowner_aw_hs && subtractive_wowner_byp && subtractive_wowner_w_end) begin
                subtractive_wowner_ahead <= 1'b1;
            end
            if (subtractive_wowner_valid && subtractive_wowner_w_end) begin
                subtractive_wowner_rptr <= subtractive_wowner_rptr + 1'b1;
