    assign cpu_128b_w_sel_subtractive = (subtractive_wowner_valid || subtractive_wowner_byp) && (subtractive_wowner_head == 3'd0) && cpu_128b_w_to_subtractive;
    assign io_128b_w_sel_subtractive = (subtractive_wowner_valid || subtractive_wowner_byp) && (subtractive_wowner_head == 3'd1) && io_128b_w_to_subtractive;
    assign acc_128b_w_sel_subtractive = (subtractive_wowner_valid || subtractive_wowner_byp) && (subtractive_wowner_head == 3'd2) && acc_128b_w_to_subtractive;
    assign atg_128b_w_sel_subtractive = (subtractive_wowner_valid || subtractive_wowner_byp) && (subtractive_wowner_head == 3'd3) && atg_128b_w_to_subtractive;
    assign cdma_128b_w_sel_subtractive = (subtractive_wowner_valid || subtractive_wowner_byp) && (subtractive_wowner_head == 3'd4) && cdma_128b_w_to_subtractive;

    // W channel (owner-gated mux across writing masters)
    assign subtractive_axi_wdata = ((cpu_128b_w_sel_subtractive && cpu_128b_wvalid) ? cpu_128b_w.data : '0) |
        ((io_128b_w_sel_subtractive && io_128b_wvalid) ? io_128b_w.data : '0) |
        ((acc_128b_w_sel_subtractive && acc_128b_wvalid) ? acc_128b_w.data : '0) |
        ((atg_128b_w_sel_subtractive && atg_128b_wvalid) ? atg_128b_w.data : '0) |
        ((cdma_128b_w_sel_subtractive && cdma_128b_wvalid) ? cdma_128b_w.data : '0);
    assign subtractive_axi_wstrb = ((cpu_128b_w_sel_subtractive && cpu_128b_wvalid) ? cpu_128b_w.strb : '0) |
        ((io_128b_w_sel_subtractive && io_128b_wvalid) ? io_128b_w.strb : '0) |
        ((acc_128b_w_sel_subtractive && acc_128b_wvalid) ? acc_128b_w.strb : '0) |
        ((atg_128b_w_sel_subtractive && atg_128b_wvalid) ? atg_128b_w.strb : '0) |
        ((cdma_128b_w_sel_subtractive && cdma_128b_wvalid) ? cdma_128b_w.strb : '0);
    assign subtractive_axi_wlast = ((cpu_128b_w_sel_subtractive && cpu_128b_wvalid) ? cpu_128b_w.last : '0) |
        ((io_128b_w_sel_subtractive && io_128b_wvalid) ? io_128b_w.last : '0) |
        ((acc_128b_w_sel_subtractive && acc_128b_wvalid) ? acc_128b_w.last : '0) |
        ((atg_128b_w_sel_subtractive && atg_128b_wvalid) ? atg_128b_w.last : '0) |
        ((cdma_128b_w_sel_subtractive && cdma_128b_wvalid) ? cdma_128b_w.last : '0);
    assign subtractive_axi_wuser = ((cpu_128b_w_sel_subtractive && cpu_128b_wvalid) ? cpu_128b_w.user : '0) |
        ((io_128b_w_sel_subtractive && io_128b_wvalid) ? io_128b_w.user : '0) |
        ((acc_128b_w_sel_subtractive && acc_128b_wvalid) ? acc_128b_w.user : '0) |
        ((atg_128b_w_sel_subtractive && atg_128b_wvalid) ? atg_128b_w.user : '0) |
        ((cdma_128b_w_sel_subtractive && cdma_128b_wvalid) ? cdma_128b_w.user : '0);
    assign subtractive_axi_wvalid = (cpu_128b_w_sel_subtractive && cpu_128b_wvalid) || (io_128b_w_sel_subtractive && io_128b_wvalid) || (acc_128b_w_sel_subtractive && acc_128b_wvalid) || (atg_128b_w_sel_subtractive && atg_128b_wvalid) || (cdma_128b_w_sel_subtractive && cdma_128b_wvalid);

    // Bready (slave -> the master whose response arbiter granted it)
    assign subtractive_axi_bready = (cpu_128b_b_rgnt_subtractive ? cpu_128b_bready : '0) |
        (io_128b_b_rgnt_subtractive ? io_128b_bready : '0) |
        (acc_128b_b_rgnt_subtractive ? acc_128b_bready : '0) |
        (atg_128b_b_rgnt_subtractive ? atg_128b_bready : '0) |
        (cdma_128b_b_rgnt_subtractive ? cdma_128b_bready : '0);

    // Bridge ID (writes) — the granted master's id
    assign subtractive_axi_bridge_id_aw = (cpu_128b_aw_gnt_subtractive ? cpu_bridge_id_aw : '0) |
        (io_128b_aw_gnt_subtractive ? io_bridge_id_aw : '0) |
        (acc_128b_aw_gnt_subtractive ? acc_bridge_id_aw : '0) |
        (atg_128b_aw_gnt_subtractive ? atg_bridge_id_aw : '0) |
        (cdma_128b_aw_gnt_subtractive ? cdma_bridge_id_aw : '0);

    // AR request slots for subtractive: arbitration at the slave pins
    assign cpu_128b_ar_slot_subtractive_in_valid = cpu_128b_ar_to_subtractive && cpu_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_cpu_128b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_128b_ar_slot_subtractive_in_valid), .wr_ready(cpu_128b_ar_slot_subtractive_in_ready), .wr_data(cpu_128b_ar),
        .rd_valid(cpu_128b_ar_slot_subtractive_valid), .rd_ready(cpu_128b_ar_slot_subtractive_ready), .rd_data(cpu_128b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign io_128b_ar_slot_subtractive_in_valid = io_128b_ar_to_subtractive && io_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_io_128b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(io_128b_ar_slot_subtractive_in_valid), .wr_ready(io_128b_ar_slot_subtractive_in_ready), .wr_data(io_128b_ar),
        .rd_valid(io_128b_ar_slot_subtractive_valid), .rd_ready(io_128b_ar_slot_subtractive_ready), .rd_data(io_128b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign acc_128b_ar_slot_subtractive_in_valid = acc_128b_ar_to_subtractive && acc_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_acc_128b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(acc_128b_ar_slot_subtractive_in_valid), .wr_ready(acc_128b_ar_slot_subtractive_in_ready), .wr_data(acc_128b_ar),
        .rd_valid(acc_128b_ar_slot_subtractive_valid), .rd_ready(acc_128b_ar_slot_subtractive_ready), .rd_data(acc_128b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign atg_128b_ar_slot_subtractive_in_valid = atg_128b_ar_to_subtractive && atg_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_atg_128b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(atg_128b_ar_slot_subtractive_in_valid), .wr_ready(atg_128b_ar_slot_subtractive_in_ready), .wr_data(atg_128b_ar),
        .rd_valid(atg_128b_ar_slot_subtractive_valid), .rd_ready(atg_128b_ar_slot_subtractive_ready), .rd_data(atg_128b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign cdma_128b_ar_slot_subtractive_in_valid = cdma_128b_ar_to_subtractive && cdma_128b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_cdma_128b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cdma_128b_ar_slot_subtractive_in_valid), .wr_ready(cdma_128b_ar_slot_subtractive_in_ready), .wr_data(cdma_128b_ar),
        .rd_valid(cdma_128b_ar_slot_subtractive_valid), .rd_ready(cdma_128b_ar_slot_subtractive_ready), .rd_data(cdma_128b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AR arbiter for subtractive: round-robin, lock until handshake ----
    logic [4:0] subtractive_ar_arb_req;
    assign subtractive_ar_arb_req = {cdma_128b_ar_slot_subtractive_valid, atg_128b_ar_slot_subtractive_valid, acc_128b_ar_slot_subtractive_valid, io_128b_ar_slot_subtractive_valid, cpu_128b_ar_slot_subtractive_valid};
    logic [2:0] subtractive_ar_arb_lock, subtractive_ar_arb_rr;
    logic subtractive_ar_arb_locked;
    wire [2:0] subtractive_ar_arb_pick = (subtractive_ar_arb_rr == 3'd0) ? (subtractive_ar_arb_req[0] ? 3'd0 : subtractive_ar_arb_req[1] ? 3'd1 : subtractive_ar_arb_req[2] ? 3'd2 : subtractive_ar_arb_req[3] ? 3'd3 : 3'd4) : 
        (subtractive_ar_arb_rr == 3'd1) ? (subtractive_ar_arb_req[1] ? 3'd1 : subtractive_ar_arb_req[2] ? 3'd2 : subtractive_ar_arb_req[3] ? 3'd3 : subtractive_ar_arb_req[4] ? 3'd4 : 3'd0) : 
        (subtractive_ar_arb_rr == 3'd2) ? (subtractive_ar_arb_req[2] ? 3'd2 : subtractive_ar_arb_req[3] ? 3'd3 : subtractive_ar_arb_req[4] ? 3'd4 : subtractive_ar_arb_req[0] ? 3'd0 : 3'd1) : 
        (subtractive_ar_arb_rr == 3'd3) ? (subtractive_ar_arb_req[3] ? 3'd3 : subtractive_ar_arb_req[4] ? 3'd4 : subtractive_ar_arb_req[0] ? 3'd0 : subtractive_ar_arb_req[1] ? 3'd1 : 3'd2) : 
        subtractive_ar_arb_req[4] ? 3'd4 : subtractive_ar_arb_req[0] ? 3'd0 : subtractive_ar_arb_req[1] ? 3'd1 : subtractive_ar_arb_req[2] ? 3'd2 : 3'd3;
    wire subtractive_ar_arb_gnt_valid = subtractive_ar_arb_locked || (|subtractive_ar_arb_req);
    wire [2:0] subtractive_ar_arb_gnt = subtractive_ar_arb_locked ? subtractive_ar_arb_lock : subtractive_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_ar_arb_lock   <= '0;
            subtractive_ar_arb_rr     <= '0;
            subtractive_ar_arb_locked <= 1'b0;
        end else begin
            if (subtractive_axi_arvalid && subtractive_axi_arready) begin
                subtractive_ar_arb_locked <= 1'b0;
                subtractive_ar_arb_rr <= (subtractive_ar_arb_gnt == 3'd4) ? 3'd0 : subtractive_ar_arb_gnt + 1'b1;
            end else if (subtractive_axi_arvalid) begin
                subtractive_ar_arb_lock   <= subtractive_ar_arb_gnt;
                subtractive_ar_arb_locked <= 1'b1;
            end
        end
    )
    wire cpu_128b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 3'd0) && subtractive_ar_arb_req[0];
    wire io_128b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 3'd1) && subtractive_ar_arb_req[1];
    wire acc_128b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 3'd2) && subtractive_ar_arb_req[2];
    wire atg_128b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 3'd3) && subtractive_ar_arb_req[3];
    wire cdma_128b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 3'd4) && subtractive_ar_arb_req[4];
    assign cpu_128b_ar_slot_subtractive_ready = cpu_128b_ar_gnt_subtractive && subtractive_axi_arready;
    assign io_128b_ar_slot_subtractive_ready = io_128b_ar_gnt_subtractive && subtractive_axi_arready;
    assign acc_128b_ar_slot_subtractive_ready = acc_128b_ar_gnt_subtractive && subtractive_axi_arready;
    assign atg_128b_ar_slot_subtractive_ready = atg_128b_ar_gnt_subtractive && subtractive_axi_arready;
    assign cdma_128b_ar_slot_subtractive_ready = cdma_128b_ar_gnt_subtractive && subtractive_axi_arready;

    // AR channel (arbitrated mux across reading masters)
    assign subtractive_axi_arid = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.id : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.id : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.id : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.id : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.id : '0);
    assign subtractive_axi_araddr = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.addr : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.addr : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.addr : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.addr : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.addr : '0);
    assign subtractive_axi_arlen = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.len : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.len : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.len : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.len : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.len : '0);
    assign subtractive_axi_arsize = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.size : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.size : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.size : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.size : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.size : '0);
    assign subtractive_axi_arburst = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.burst : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.burst : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.burst : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.burst : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.burst : '0);
    assign subtractive_axi_arlock = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.lock : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.lock : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.lock : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.lock : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.lock : '0);
    assign subtractive_axi_arcache = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.cache : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.cache : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.cache : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.cache : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.cache : '0);
    assign subtractive_axi_arprot = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.prot : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.prot : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.prot : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.prot : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.prot : '0);
    assign subtractive_axi_arqos = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.qos : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.qos : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.qos : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.qos : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.qos : '0);
    assign subtractive_axi_arregion = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.region : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.region : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.region : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.region : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.region : '0);
    assign subtractive_axi_aruser = (cpu_128b_ar_gnt_subtractive ? cpu_128b_ar_slot_subtractive.user : '0) |
        (io_128b_ar_gnt_subtractive ? io_128b_ar_slot_subtractive.user : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_128b_ar_slot_subtractive.user : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_128b_ar_slot_subtractive.user : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_128b_ar_slot_subtractive.user : '0);
    assign subtractive_axi_arvalid = cpu_128b_ar_gnt_subtractive || io_128b_ar_gnt_subtractive || acc_128b_ar_gnt_subtractive || atg_128b_ar_gnt_subtractive || cdma_128b_ar_gnt_subtractive;

    // Rready (slave -> the master whose response arbiter granted it)
    assign subtractive_axi_rready = (cpu_128b_r_rgnt_subtractive ? cpu_128b_rready : '0) |
        (io_128b_r_rgnt_subtractive ? io_128b_rready : '0) |
        (acc_128b_r_rgnt_subtractive ? acc_128b_rready : '0) |
        (atg_128b_r_rgnt_subtractive ? atg_128b_rready : '0) |
        (cdma_128b_r_rgnt_subtractive ? cdma_128b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign subtractive_axi_bridge_id_ar = (cpu_128b_ar_gnt_subtractive ? cpu_bridge_id_ar : '0) |
        (io_128b_ar_gnt_subtractive ? io_bridge_id_ar : '0) |
        (acc_128b_ar_gnt_subtractive ? acc_bridge_id_ar : '0) |
        (atg_128b_ar_gnt_subtractive ? atg_bridge_id_ar : '0) |
        (cdma_128b_ar_gnt_subtractive ? cdma_bridge_id_ar : '0);


    // ================================================================
    // W destination FIFOs (per master width-path)
    // ================================================================
    // cpu 32b path -> mem2 (16 deep: max_outstanding)
    logic [0:0] cpu_32b_wdest_mem [16];
    logic [4:0] cpu_32b_wdest_wptr, cpu_32b_wdest_rptr;
    wire [0:0] cpu_32b_wdest_enc = 1'd0;
    wire cpu_32b_wdest_push = cpu_32b_awvalid && cpu_32b_awready;
    wire cpu_32b_wdest_pop  = cpu_32b_wvalid && cpu_32b_wready && cpu_32b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            cpu_32b_wdest_wptr <= '0;
            cpu_32b_wdest_rptr <= '0;
        end else begin
            if (cpu_32b_wdest_push) begin
                cpu_32b_wdest_mem[cpu_32b_wdest_wptr[3:0]] <= cpu_32b_wdest_enc;
                cpu_32b_wdest_wptr <= cpu_32b_wdest_wptr + 1'b1;
            end
            if (cpu_32b_wdest_pop) begin
                cpu_32b_wdest_rptr <= cpu_32b_wdest_rptr + 1'b1;
            end
        end
    )
    wire cpu_32b_wdest_valid = (cpu_32b_wdest_wptr != cpu_32b_wdest_rptr);
    assign cpu_32b_wdest_full = (cpu_32b_wdest_wptr[4] != cpu_32b_wdest_rptr[4]) && (cpu_32b_wdest_wptr[3:0] == cpu_32b_wdest_rptr[3:0]);
    wire [0:0] cpu_32b_wdest_head = cpu_32b_wdest_mem[cpu_32b_wdest_rptr[3:0]];
    assign cpu_32b_w_to_mem2 = cpu_32b_wdest_valid && (cpu_32b_wdest_head == 1'd0);
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) cpu_32b_wlive_mem2 <= '0;
        else cpu_32b_wlive_mem2 <= cpu_32b_wlive_mem2 + 5'((cpu_32b_wdest_push && (cpu_32b_wdest_enc == 1'd0))) - 5'((cpu_32b_wdest_pop && (cpu_32b_wdest_head == 1'd0)));
    )

    // cpu 64b path -> mem0, mem1, bram (16 deep: max_outstanding)
    logic [1:0] cpu_64b_wdest_mem [16];
    logic [4:0] cpu_64b_wdest_wptr, cpu_64b_wdest_rptr;
    wire [1:0] cpu_64b_wdest_enc = cpu_64b_aw_to_mem1 ? 2'd1 : cpu_64b_aw_to_bram ? 2'd2 : 2'd0;
    wire cpu_64b_wdest_push = cpu_64b_awvalid && cpu_64b_awready;
    wire cpu_64b_wdest_pop  = cpu_64b_wvalid && cpu_64b_wready && cpu_64b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            cpu_64b_wdest_wptr <= '0;
            cpu_64b_wdest_rptr <= '0;
        end else begin
            if (cpu_64b_wdest_push) begin
                cpu_64b_wdest_mem[cpu_64b_wdest_wptr[3:0]] <= cpu_64b_wdest_enc;
                cpu_64b_wdest_wptr <= cpu_64b_wdest_wptr + 1'b1;
            end
            if (cpu_64b_wdest_pop) begin
                cpu_64b_wdest_rptr <= cpu_64b_wdest_rptr + 1'b1;
            end
        end
    )
    wire cpu_64b_wdest_valid = (cpu_64b_wdest_wptr != cpu_64b_wdest_rptr);
    assign cpu_64b_wdest_full = (cpu_64b_wdest_wptr[4] != cpu_64b_wdest_rptr[4]) && (cpu_64b_wdest_wptr[3:0] == cpu_64b_wdest_rptr[3:0]);
    wire [1:0] cpu_64b_wdest_head = cpu_64b_wdest_mem[cpu_64b_wdest_rptr[3:0]];
    assign cpu_64b_w_to_mem0 = cpu_64b_wdest_valid && (cpu_64b_wdest_head == 2'd0);
    assign cpu_64b_w_to_mem1 = cpu_64b_wdest_valid && (cpu_64b_wdest_head == 2'd1);
    assign cpu_64b_w_to_bram = cpu_64b_wdest_valid && (cpu_64b_wdest_head == 2'd2);

    // cpu 128b path -> ddr, subtractive (16 deep: max_outstanding)
    logic [0:0] cpu_128b_wdest_mem [16];
    logic [4:0] cpu_128b_wdest_wptr, cpu_128b_wdest_rptr;
    wire [0:0] cpu_128b_wdest_enc = cpu_128b_aw_to_subtractive ? 1'd1 : 1'd0;
    wire cpu_128b_wdest_push = cpu_128b_awvalid && cpu_128b_awready;
    wire cpu_128b_wdest_pop  = cpu_128b_wvalid && cpu_128b_wready && cpu_128b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            cpu_128b_wdest_wptr <= '0;
            cpu_128b_wdest_rptr <= '0;
        end else begin
            if (cpu_128b_wdest_push) begin
                cpu_128b_wdest_mem[cpu_128b_wdest_wptr[3:0]] <= cpu_128b_wdest_enc;
                cpu_128b_wdest_wptr <= cpu_128b_wdest_wptr + 1'b1;
            end
            if (cpu_128b_wdest_pop) begin
                cpu_128b_wdest_rptr <= cpu_128b_wdest_rptr + 1'b1;
            end
        end
    )
    wire cpu_128b_wdest_valid = (cpu_128b_wdest_wptr != cpu_128b_wdest_rptr);
    assign cpu_128b_wdest_full = (cpu_128b_wdest_wptr[4] != cpu_128b_wdest_rptr[4]) && (cpu_128b_wdest_wptr[3:0] == cpu_128b_wdest_rptr[3:0]);
    wire [0:0] cpu_128b_wdest_head = cpu_128b_wdest_mem[cpu_128b_wdest_rptr[3:0]];
    assign cpu_128b_w_to_ddr = cpu_128b_wdest_valid && (cpu_128b_wdest_head == 1'd0);
    assign cpu_128b_w_to_subtractive = cpu_128b_wdest_valid && (cpu_128b_wdest_head == 1'd1);

    // io 32b path -> mem2 (16 deep: max_outstanding)
    logic [0:0] io_32b_wdest_mem [16];
    logic [4:0] io_32b_wdest_wptr, io_32b_wdest_rptr;
    wire [0:0] io_32b_wdest_enc = 1'd0;
    wire io_32b_wdest_push = io_32b_awvalid && io_32b_awready;
    wire io_32b_wdest_pop  = io_32b_wvalid && io_32b_wready && io_32b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            io_32b_wdest_wptr <= '0;
            io_32b_wdest_rptr <= '0;
        end else begin
            if (io_32b_wdest_push) begin
                io_32b_wdest_mem[io_32b_wdest_wptr[3:0]] <= io_32b_wdest_enc;
                io_32b_wdest_wptr <= io_32b_wdest_wptr + 1'b1;
